INSERT INTO public.deep_cases (id, market_id, day, slot, content, tags) VALUES
($ml$89ed86c1-d304-5e00-95c4-f609881be171$ml$::uuid, $ml$logistics$ml$, 1, 1, $ml${"id": "logistics-d1-c1", "title": "A $46 billion forwarder", "lessonTitle": "Who moves the world's goods", "slot": 1, "type": "apply", "brief": {"headline": "DSV closed its $16 billion purchase of Schenker from Deutsche Bahn in 2025. The combined group has about $46 billion of annual revenue and 160,000 employees.", "kicker": "Apply the rule: who owns, who moves, who manages?", "fullText": "DSV agreed to buy Schenker from the German railway in September 2024, the largest deal in DSV's history. It closed at the end of April 2025.\n\nSchenker brings DSV a bigger presence in Germany across maritime, road, rail and air cargo. DSV expects about $600 million of extra operating profit from Schenker this year. Its CEO says the deal makes DSV a world-leading player in transport and logistics.", "sources": [{"url": "https://maritime-executive.com/article/dsv-completes-acquisition-of-schenker-creating-logistics-giant", "label": "Maritime Executive, DSV completes acquisition of Schenker"}, {"url": "https://scm.ncsu.edu/?p=942", "label": "NC State Supply Chain Resource Cooperative, 3PL and 4PL"}]}, "evidence": {"kind": "multipleChoice", "prompt": "A firm arranges sea, air, road and rail freight for shippers and runs their logistics. What is it?", "options": ["A 3PL: it manages logistics for the shippers", "A carrier, since the freight moves on its own contracts", "A 4PL, since it uses several transport modes at once"], "correctIndex": 0, "explanation": "A 3PL manages logistics for shippers well beyond one truck or ship. A 4PL manages the other 3PLs."}, "numbers": {"kind": "numberSense", "prompt": "About how many people work for DSV after buying Schenker?", "min": 0, "max": 250, "value": 160, "unit": "K", "explanation": "About 160,000 employees, with about $46 billion of annual revenue."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at DSV for a graduate role. They ask what kind of company they are.", "prompt": "Which answer shows you know the map?", "options": ["A shipping line that owns the vessels it books", "A 4PL that only manages other firms' 3PLs", "A 3PL and forwarder that arranges freight"], "correctIndex": 2, "consequences": ["Forwarders book space on carriers; that is a different business.", "A 4PL coordinates other 3PLs, which is not their core business.", "You name the player type, which tells them you know the industry."], "explanation": "DSV arranges and manages freight for shippers across modes. That is 3PL and forwarding work."}, "proReasoning": "Strong candidates name the player type first. It shows which skills the role needs, from carrier buying to customer accounts.", "commonMistake": "Calling every logistics company a carrier. The interviewer hears that you have not looked at the map.", "mentalModel": "Say what the company owns, moves and manages."}, "invest": {"call": {"kind": "theCall", "situation": "DSV paid $16 billion for Schenker and expects $600 million more operating profit this year.", "prompt": "What is the key question for an investor?", "options": ["Can DSV merge two networks and keep customers?", "Will global freight volumes double after the deal?", "Does DSV now own enough ships and planes?"], "correctIndex": 0, "consequences": ["Integration risk is where big logistics deals succeed or fail.", "The deal case does not rest on a doubling of volume.", "Ship ownership is not what a forwarder sells."], "explanation": "A forwarder sells coordination and customer relationships. Keeping both through a merger decides the return."}, "proReasoning": "Investors in big logistics deals watch integration: systems, people and customers. That is where promised profit gains are won or lost.", "commonMistake": "Treating the deal as a capacity grab. Forwarders buy networks and customers, not trucks or ships.", "mentalModel": "Judge the merger by what it keeps, not what it adds."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build software for freight forwarders. DSV and Schenker now run two sets of systems.", "prompt": "Where is the opening?", "options": ["Route software for one small trucking firm", "Tools that help merged forwarders join systems", "A rival forwarder to compete with DSV head on"], "correctIndex": 1, "consequences": ["That misses the coordination problem the deal creates.", "Every large merger needs data and systems stitched together.", "Matching a $46 billion group from scratch is a long road."], "explanation": "Coordination across systems is the hard part of a merger. That is where software helps."}, "proReasoning": "Founders look for pain created by big events. Joining two forwarders is months of messy integration work.", "commonMistake": "Building for the biggest name instead of the biggest problem.", "mentalModel": "Sell to the pain the deal creates."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that a forwarder became one of the biggest logistics firms without being a carrier.", "prompt": "How is that possible?", "options": ["It quietly owns most of the trucks it uses", "It mostly moves its own products for sale", "It earns by arranging freight, not owning it"], "correctIndex": 2, "consequences": ["Forwarders mostly buy capacity from carriers.", "A forwarder moves goods for other companies.", "You see that coordination itself is a business."], "explanation": "Shippers pay forwarders to plan and manage moves. The trucks, ships and planes often belong to others."}, "proReasoning": "Look at who owns the goods, who moves them and who manages the movers. Big money sits in all three.", "commonMistake": "Assuming the biggest logistics firms must own the most vehicles.", "mentalModel": "Managing the movers is a business too."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1b5f7113637d$ml$]::text[]),
($ml$2a2b308d-2d5a-5358-9027-ae4f2d35f82b$ml$::uuid, $ml$logistics$ml$, 1, 2, $ml${"id": "logistics-d1-c2", "title": "Who manages the movers", "lessonTitle": "Who moves the world's goods", "slot": 2, "type": "connect", "brief": {"headline": "US businesses spent $2.58 trillion on logistics in 2024, about 8.8% of GDP. Trucks moved more than 72% of domestic freight by weight.", "kicker": "Connect the two ideas: the player map and the money.", "fullText": "Carriers move the goods: trucking firms, railroads, airlines and shipping lines. A 3PL manages logistics for a shipper, and a 4PL integrates the whole chain and manages other 3PLs.\n\nThe money behind that map is large. CSCMP put 2024 US logistics costs at $2.58 trillion, up 5.4%, with full truckload spending at $387 billion and private or dedicated fleets at $541.4 billion.", "sources": [{"url": "https://www.freightwaves.com/news/logistics-gdp-share-rose-in-24-not-likely-to-drop-cscmp-report", "label": "FreightWaves on the CSCMP State of Logistics"}, {"url": "https://scm.ncsu.edu/?p=942", "label": "NC State Supply Chain Resource Cooperative, 3PL and 4PL"}, {"url": "https://trucking.org/news-insights/ata-releases-latest-edition-american-trucking-trends-0", "label": "ATA, American Trucking Trends 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Carrier, 3PL or 4PL?", "buckets": ["Carrier", "3PL", "4PL"], "items": [{"text": "A railroad hauling grain", "bucket": 0}, {"text": "An airline flying cargo", "bucket": 0}, {"text": "Runs a retailer's warehouses", "bucket": 1}, {"text": "Books trucks for a shipper's loads", "bucket": 1}, {"text": "Oversees all of a brand's 3PLs", "bucket": 2}], "explanation": "Carriers move goods, 3PLs manage logistics for shippers, and 4PLs manage the 3PLs."}, "numbers": {"kind": "numberSense", "prompt": "To the nearest whole number, what share of US GDP went to logistics in 2024?", "min": 0, "max": 20, "value": 9, "unit": "%", "explanation": "About 8.8% of nominal GDP, or $2.58 trillion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You can join a carrier, a 3PL or a 4PL. You enjoy planning more than running equipment.", "prompt": "Which fits you best?", "options": ["A 3PL or 4PL, where the job is planning", "A carrier, where you manage drivers and fleets", "Whichever one pays most in the first year"], "correctIndex": 0, "consequences": ["You match the role to the work you like.", "Carrier jobs center on running equipment.", "Pay alone ignores what the job asks of you."], "explanation": "Carriers run equipment. 3PLs and 4PLs plan and coordinate, which fits a planner."}, "proReasoning": "Good candidates pick the player type that matches their skills. Each type hires for different work.", "commonMistake": "Applying everywhere without knowing which type of company does what.", "mentalModel": "Match the player type to the work you want."}, "invest": {"call": {"kind": "theCall", "situation": "Logistics costs $2.58 trillion a year in the US, about 8.8% of GDP.", "prompt": "What does that size mean for an investor?", "options": ["The market is too big to change", "Small efficiency gains can move large sums", "Every logistics company is a good investment"], "correctIndex": 1, "consequences": ["Large markets still shift as costs and tools change.", "You see why a 1% saving is worth billions.", "Size says nothing about one company's returns."], "explanation": "At $2.58 trillion, a 1% saving is about $26 billion. That is why efficiency stories matter."}, "proReasoning": "Investors use market size to judge what is at stake, then look for who captures the savings.", "commonMistake": "Confusing a big market with a good investment.", "mentalModel": "Size tells you the stakes, not the winner."}, "build_startup": {"call": {"kind": "theCall", "situation": "Private and dedicated fleets cost US shippers $541.4 billion in 2024.", "prompt": "What does that suggest for a logistics startup?", "options": ["Only for-hire carriers ever buy software", "Private fleets are too small to sell to", "Shippers running their own fleets need tools"], "correctIndex": 2, "consequences": ["Private fleets face the same planning problems.", "At $541.4 billion, they are bigger than truckload spending.", "You spot a large, often overlooked group of buyers."], "explanation": "Private fleets cost more than the $387 billion spent on full truckload. That is a big market to serve."}, "proReasoning": "Founders size each customer group. Private fleets are a large segment with their own needs.", "commonMistake": "Building only for carriers and missing shippers with their own trucks.", "mentalModel": "Follow the spending to find the buyer."}, "curiosity": {"call": {"kind": "theCall", "situation": "You learn trucks move more than 72% of US freight by weight.", "prompt": "Why does that matter for everyone else in logistics?", "options": ["Trucking problems ripple through the chain", "Rail and ships no longer matter at all", "It means freight is cheap to move now"], "correctIndex": 0, "consequences": ["You see why truck capacity shapes everyone's plans.", "Other modes still carry long and heavy hauls.", "Share by weight says nothing about price."], "explanation": "With most freight on trucks, a trucking crunch hits shippers, 3PLs and stores at once."}, "proReasoning": "Find the mode that carries the most. Its bottlenecks become everyone's problem.", "commonMistake": "Treating the modes as separate worlds that never affect each other.", "mentalModel": "Watch the mode that carries the load."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:dda87dd02d5e$ml$]::text[]),
($ml$64f0e6d5-472d-5353-9ad4-13190299e09f$ml$::uuid, $ml$logistics$ml$, 1, 3, $ml${"id": "logistics-d1-c3", "title": "Asked to become a 4PL", "lessonTitle": "Who moves the world's goods", "slot": 3, "type": "decide", "brief": {"headline": "You run a 3PL that manages one region of a retailer's warehouses. The retailer asks you to oversee all its 3PLs nationwide.", "kicker": "Decide: take on the role of managing the movers?", "fullText": "A 3PL manages logistics for a shipper. A 4PL integrates the whole supply chain and manages the other 3PLs, often including competitors.\n\nThe retailer wants one partner accountable for every warehouse and carrier. The role pays for coordination, not for running buildings, and it means directing rivals you compete with elsewhere.", "sources": [{"url": "https://scm.ncsu.edu/?p=942", "label": "NC State Supply Chain Resource Cooperative, 3PL and 4PL"}]}, "evidence": {"kind": "faceOff", "prompt": "Which role manages the other 3PLs?", "left": {"name": "4PL", "note": "Integrates the whole supply chain"}, "right": {"name": "3PL", "note": "Manages logistics for a shipper"}, "correctIndex": 0, "explanation": "A 4PL sits above the 3PLs and coordinates them for the shipper."}, "numbers": {"kind": "numberSense", "prompt": "How many billion dollars did US private and dedicated fleets cost in 2024?", "min": 0, "max": 800, "value": 541, "unit": "B", "explanation": "About $541.4 billion, more than the $387 billion spent on full truckload."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks you to lead the new 4PL team that will direct rival 3PLs.", "prompt": "What skill matters most in that job?", "options": ["Negotiating truck prices one load at a time", "Getting partners you do not control to deliver", "Running a busy warehouse floor yourself"], "correctIndex": 1, "consequences": ["Load pricing is a narrower task inside the chain.", "You see that a 4PL leads through influence and data.", "A 4PL coordinates buildings others run."], "explanation": "A 4PL manages other companies. Influence, data and clear targets matter more than floor skills."}, "proReasoning": "Strong 4PL leads set shared targets and report on every partner. They manage outcomes, not tasks.", "commonMistake": "Managing rival 3PLs as if they were your own staff.", "mentalModel": "Lead partners with targets and data."}, "invest": {"call": {"kind": "theCall", "situation": "A listed 3PL says it will add 4PL contracts that pay for coordination only.", "prompt": "What should an investor check first?", "options": ["How many new warehouses it plans to build", "Whether truck rates will rise next year", "Whether the fees beat the cost of its planners"], "correctIndex": 2, "consequences": ["4PL work needs few new buildings.", "Truck rates matter less to a fee-based role.", "You test if coordination fees make money on their own."], "explanation": "A 4PL earns fees for planning. The margin depends on fees versus the cost of the people doing it."}, "proReasoning": "Investors split asset income from fee income. Fee businesses need little capital but must cover their payroll.", "commonMistake": "Valuing coordination fees like warehouse revenue.", "mentalModel": "Check if the fees cover the planners."}, "build_startup": {"call": {"kind": "theCall", "situation": "You sell to a retailer that has just named a 4PL to manage its 3PLs.", "prompt": "What will the 4PL need most?", "options": ["One view of every partner's orders and stock", "A faster forklift for a single warehouse", "A new brand of truck for its own fleet"], "correctIndex": 0, "consequences": ["You target the visibility a 4PL cannot work without.", "One building's gear is the 3PL's concern.", "Vehicles are a carrier choice."], "explanation": "Managing several 3PLs means pulling their data into one place. That is a software problem."}, "proReasoning": "Founders who sell to 4PLs solve visibility across companies, the core of the job.", "commonMistake": "Building for one warehouse when the buyer manages many.", "mentalModel": "Give the coordinator one view."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why a retailer would pay one firm just to manage its other logistics firms.", "prompt": "What is the reason?", "options": ["It lets trucks drive faster on highways", "One partner answers for the whole chain", "It removes the need for warehouses"], "correctIndex": 1, "consequences": ["Coordination does not change road speeds.", "You see the value of a single point of responsibility.", "The goods still sit in warehouses."], "explanation": "With many 3PLs, problems fall between companies. A 4PL owns the whole result."}, "proReasoning": "Ask who is responsible when things go wrong. That answer explains the 4PL role.", "commonMistake": "Thinking more middlemen always means more waste.", "mentalModel": "Someone has to own the whole chain."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:881d70a6f95b$ml$]::text[]),
($ml$2053de16-f887-56c5-8424-d8db878b83c1$ml$::uuid, $ml$logistics$ml$, 2, 1, $ml${"id": "logistics-d2-c1", "title": "UPS sells its broker", "lessonTitle": "Asset-heavy vs asset-light", "slot": 1, "type": "apply", "brief": {"headline": "In September 2024, UPS sold its freight broker Coyote Logistics to RXO for $1.025 billion. RXO became the third-largest broker in North America.", "kicker": "Apply the rule: own capacity or sell access to it?", "fullText": "UPS runs one of the largest owned delivery networks. Under its \"better not bigger\" strategy, it chose to focus on parcels and sold Coyote, an asset-light broker that books other companies' trucks.\n\nFor RXO, the deal created a business with about a $7 billion top line and 150,000 carriers providing capacity. Coyote is strong in food and beverage and mostly works with large carriers and private fleets.", "sources": [{"url": "https://freightwaves.com/news/rxo-completes-1-025b-acquisition-of-coyote-logistics", "label": "FreightWaves, RXO completes $1.025B acquisition of Coyote Logistics"}, {"url": "https://www.sec.gov/Archives/edgar/data/1043277/000104327726000009/chrw-20251231.htm", "label": "C. H. Robinson 10-K, 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Asset-heavy or asset-light?", "buckets": ["Asset-heavy", "Asset-light"], "items": [{"text": "UPS parcel network", "bucket": 0}, {"text": "Owns sorting hubs and vans", "bucket": 0}, {"text": "Coyote Logistics", "bucket": 1}, {"text": "Books 150,000 outside carriers", "bucket": 1}], "explanation": "UPS owns its network. Coyote and RXO sell access to trucks other companies own."}, "numbers": {"kind": "numberSense", "prompt": "About how many billion dollars did RXO pay UPS for Coyote?", "min": 0, "max": 3, "value": 1, "unit": "B", "explanation": "RXO paid $1.025 billion, about $1.0 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at RXO after the Coyote deal. They ask how their model differs from UPS.", "prompt": "What is the sharpest answer?", "options": ["RXO sells access to trucks; UPS owns them", "RXO and UPS both own and run their fleets", "RXO delivers parcels door to door like UPS"], "correctIndex": 0, "consequences": ["You show you understand the two ways to make money in freight.", "RXO is a broker and owns little equipment.", "RXO brokers truckloads; UPS is the parcel carrier."], "explanation": "Brokers match shippers with outside carriers. UPS owns hubs and vehicles."}, "proReasoning": "Naming the model shows you know what the job involves: sales and carrier relations, not fleet upkeep.", "commonMistake": "Describing a broker as if it ran its own trucks.", "mentalModel": "Name the model before you name the job."}, "invest": {"call": {"kind": "theCall", "situation": "UPS sold an asset-light broker to focus on its owned parcel network.", "prompt": "What trade-off did UPS accept?", "options": ["No change in its risk profile", "More focus, but more exposure to fixed costs", "Lower fixed costs and more flexibility"], "correctIndex": 1, "consequences": ["Shedding a broker does change the mix of risk.", "You see that owning a network means carrying it through downturns.", "Selling the light business left UPS more asset-heavy."], "explanation": "Owned networks carry fixed costs in a slump. Brokers flex but earn thin margins."}, "proReasoning": "Investors check the mix of owned and brokered revenue. It shapes how earnings swing in a downturn.", "commonMistake": "Assuming a sale always lowers risk.", "mentalModel": "Know what kind of cost you are left holding."}, "build_startup": {"call": {"kind": "theCall", "situation": "RXO now books loads with 150,000 carriers after combining with Coyote.", "prompt": "Where can a startup help a broker of that size?", "options": ["Building a rival national parcel network", "Selling new trucks to RXO in bulk", "Tools to vet and match carriers at scale"], "correctIndex": 2, "consequences": ["A parcel network needs billions in assets.", "Brokers do not buy trucks.", "Matching and vetting that many carriers is a software problem."], "explanation": "At 150,000 carriers, matching and checking capacity is mostly software."}, "proReasoning": "Founders who serve brokers solve matching, pricing and carrier trust at scale.", "commonMistake": "Pitching hardware to a company built on owning little.", "mentalModel": "Help the matcher match faster."}, "curiosity": {"call": {"kind": "theCall", "situation": "You notice UPS sold a business that was growing in freight.", "prompt": "Why would a big carrier sell it?", "options": ["To focus on its core owned network", "Because brokers lose money in every year", "To stop moving freight entirely"], "correctIndex": 0, "consequences": ["You see a strategy choice, not a rescue.", "Brokers can earn well in good markets.", "UPS still moves huge volumes of parcels."], "explanation": "UPS chose \"better not bigger\" and its parcel network over a light side business."}, "proReasoning": "Companies sell good units when they do not fit the core plan.", "commonMistake": "Assuming a company only sells what is failing.", "mentalModel": "Focus can be a reason to sell."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1ff717cda30c$ml$]::text[]),
($ml$4fef565e-483c-54ab-8c94-c5f9314f53f7$ml$::uuid, $ml$logistics$ml$, 2, 2, $ml${"id": "logistics-d2-c2", "title": "Two models, one day 1 map", "lessonTitle": "Asset-heavy vs asset-light", "slot": 2, "type": "connect", "brief": {"headline": "C.H. Robinson had about $16.2 billion of 2025 revenue while owning very little equipment. J.B. Hunt owns 18,843 tractors and about 125,000 containers.", "kicker": "Connect day 1 and day 2: player types and their models.", "fullText": "Day 1 sorted logistics into carriers, 3PLs and 4PLs. Day 2 shows the money behind two of them.\n\nC.H. Robinson, a broker and 3PL, kept about $2.59 billion of adjusted gross profit after paying for transportation, about 16% of revenue. J.B. Hunt, a carrier, owns its tractors and containers and employs its drivers. One sells access to capacity; the other owns it.", "sources": [{"url": "https://www.sec.gov/Archives/edgar/data/1043277/000104327726000009/chrw-20251231.htm", "label": "C. H. Robinson 10-K, 2025"}, {"url": "https://www.sec.gov/Archives/edgar/data/728535/000143774926005294/jbht20251231_10k.htm", "label": "J. B. Hunt 10-K, 2025"}, {"url": "https://scm.ncsu.edu/?p=942", "label": "NC State Supply Chain Resource Cooperative, 3PL and 4PL"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The carrier in this story owns 18,843 tractors.", "The broker kept about 16% of revenue as adjusted gross profit.", "The broker directly employs the drivers who haul its freight."], "fakeIndex": 2, "explanation": "The broker says it does not directly employ the drivers who haul its freight."}, "numbers": {"kind": "numberSense", "prompt": "How many intermodal containers does J.B. Hunt own, roughly?", "min": 0, "max": 200, "value": 125, "unit": "K", "explanation": "About 125,000 intermodal containers, plus 18,843 tractors."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You compare offers from C.H. Robinson and J.B. Hunt.", "prompt": "Which question tells you most about the day-to-day job?", "options": ["Which one has the nicer head office?", "Does it own the capacity or broker it?", "Which one has the larger revenue?"], "correctIndex": 1, "consequences": ["The office tells you nothing about the work.", "The model shapes whether you sell, buy capacity or run fleets.", "Revenue size says little about your tasks."], "explanation": "Brokers hire for sales and carrier relations. Asset carriers also hire for fleets and maintenance."}, "proReasoning": "Candidates who ask about the model know what each job will demand.", "commonMistake": "Choosing on brand name alone.", "mentalModel": "Ask whether they own or broker."}, "invest": {"call": {"kind": "theCall", "situation": "Freight demand falls 10%. You own shares in a broker and an asset-heavy carrier.", "prompt": "Which is likely to feel the fixed costs more?", "options": ["The broker, because it owns more trucks", "Both feel it the same way", "The asset-heavy carrier"], "correctIndex": 2, "consequences": ["Brokers own very little equipment.", "Their cost structures differ sharply.", "Owned trucks and wages keep costing money when loads fall."], "explanation": "Carriers carry tractors and drivers through a slump. Brokers can buy less capacity."}, "proReasoning": "Investors model a downturn for each model. Fixed costs decide who bleeds.", "commonMistake": "Treating all freight stocks as one bet.", "mentalModel": "Model the downturn by cost structure."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want to start a freight company with little capital.", "prompt": "Which model fits?", "options": ["Brokerage: little equipment, thin margins", "An asset carrier with a large fleet", "A railroad"], "correctIndex": 0, "consequences": ["You can start without buying trucks.", "A fleet needs heavy capital up front.", "Railroads need enormous fixed assets."], "explanation": "Brokers need little capital, but must win on matching and margins."}, "proReasoning": "Founders pick the model their capital can support, then plan for thin margins.", "commonMistake": "Starting asset-heavy before proving demand.", "mentalModel": "Match the model to your capital."}, "curiosity": {"call": {"kind": "theCall", "situation": "You learn a broker kept only about 16% of its revenue after paying carriers.", "prompt": "Where did the other 84% go?", "options": ["Into corporate taxes for the year", "To the carriers it paid to haul loads", "Into buying new trucks for itself"], "correctIndex": 1, "consequences": ["Taxes come out of profit, not revenue.", "You see that most broker revenue passes through to carriers.", "Brokers own very little equipment."], "explanation": "Adjusted gross profit is revenue minus purchased transportation. Most of the money passes to carriers."}, "proReasoning": "Look at gross profit, not revenue, to size a broker.", "commonMistake": "Mistaking a broker's revenue for money it keeps.", "mentalModel": "Revenue is not what a broker keeps."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a078a6dcd831$ml$]::text[]),
($ml$5fe7325d-6007-52ed-b604-bfc5f4e7aa23$ml$::uuid, $ml$logistics$ml$, 2, 3, $ml${"id": "logistics-d2-c3", "title": "Buy trucks or keep brokering?", "lessonTitle": "Asset-heavy vs asset-light", "slot": 3, "type": "decide", "brief": {"headline": "You run a growing freight broker. A big customer offers a three-year contract if you add 200 of your own trucks.", "kicker": "Decide: should a broker turn into a carrier?", "fullText": "Brokers like C.H. Robinson own very little equipment and live on the spread between what shippers pay and what carriers receive. Carriers like J.B. Hunt own tractors and employ drivers.\n\nOwning trucks gives control of capacity but brings fixed costs that stay through downturns. Brokering needs little capital but competes on thin margins.", "sources": [{"url": "https://www.sec.gov/Archives/edgar/data/1043277/000104327726000009/chrw-20251231.htm", "label": "C. H. Robinson 10-K, 2025"}, {"url": "https://www.sec.gov/Archives/edgar/data/728535/000143774926005294/jbht20251231_10k.htm", "label": "J. B. Hunt 10-K, 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Which model keeps costs flexible when freight falls?", "left": {"name": "Brokering", "note": "Buys capacity load by load"}, "right": {"name": "Owning trucks", "note": "Pays for tractors and drivers"}, "correctIndex": 0, "explanation": "A broker can buy less capacity. Owned trucks keep costing money."}, "numbers": {"kind": "numberSense", "prompt": "How many billion dollars of adjusted gross profit did C.H. Robinson report for 2025?", "min": 0, "max": 4, "value": 2.6, "unit": "B", "explanation": "About $2.59 billion, about 16% of its $16.2 billion revenue."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You lead carrier sales at the broker. The CEO asks your view on buying 200 trucks.", "prompt": "What do you raise first?", "options": ["How fast we can paint the new trucks", "Whether our carriers will thank us for it", "Who runs drivers and repairs, which we lack"], "correctIndex": 2, "consequences": ["Branding is the least of the changes.", "Carriers may see you as a competitor.", "You name the new skills the move requires."], "explanation": "Owning trucks means hiring drivers and running maintenance, skills a broker rarely has."}, "proReasoning": "Good operators name the capabilities a new model needs before they back it.", "commonMistake": "Assuming broker skills carry over to running a fleet.", "mentalModel": "Name the skills the new model needs."}, "invest": {"call": {"kind": "theCall", "situation": "The broker's shares trade on its light model. It may add 200 owned trucks.", "prompt": "How might investors react?", "options": ["Ask about fixed costs if the contract ends", "Cheer, since owning assets is always safer", "Ignore it as too small to matter"], "correctIndex": 0, "consequences": ["You see the model shift changes the risk profile.", "Assets bring fixed costs, not safety.", "A model change matters even at small scale."], "explanation": "A three-year contract does not cover truck costs for a full truck life. Investors will price that."}, "proReasoning": "Investors watch whether a company keeps the model they valued it for.", "commonMistake": "Assuming assets always add value.", "mentalModel": "Ask who pays when the contract ends."}, "build_startup": {"call": {"kind": "theCall", "situation": "You founded the broker two years ago with little capital.", "prompt": "What is the safer way to say yes to the customer?", "options": ["Turn the customer down outright today", "Contract dedicated capacity from carriers", "Borrow to buy all 200 trucks right now"], "correctIndex": 1, "consequences": ["Declining loses a big customer.", "You win the deal without carrying the fleet.", "Debt-funded trucks can sink a young company in a slump."], "explanation": "Dedicated contracts with carriers give the customer capacity without your capital."}, "proReasoning": "Founders find ways to say yes without taking on risk they cannot carry.", "commonMistake": "Changing your whole model for one customer.", "mentalModel": "Win the deal, keep the model."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why most brokers never buy their own trucks.", "prompt": "What is the main reason?", "options": ["It is illegal for brokers to own trucks", "Trucks are rarely used for freight now", "Trucks bring costs that stay in downturns"], "correctIndex": 2, "consequences": ["Many firms run both models.", "Trucks move most US freight.", "You see the trade-off between control and flexibility."], "explanation": "Owning capacity gives control but adds costs that do not shrink when freight falls."}, "proReasoning": "Every freight model trades control against flexibility.", "commonMistake": "Thinking owning is always better than renting.", "mentalModel": "Control costs flexibility."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:629ec89ab6b4$ml$]::text[]),
($ml$17d76485-b7e1-52b6-8d7a-32e0a9600351$ml$::uuid, $ml$logistics$ml$, 3, 1, $ml${"id": "logistics-d3-c1", "title": "UPS shrinks its biggest customer", "lessonTitle": "Who holds the power in delivery", "slot": 1, "type": "apply", "brief": {"headline": "In January 2025, UPS said it would cut the Amazon volume it delivers by more than 50% by the second half of 2026. Amazon was 11.8% of UPS revenue.", "kicker": "Apply the rule: who controls the network holds the power.", "fullText": "About 20% to 25% of the volume in UPS's US network was tied to Amazon. CEO Carol Tomé said Amazon is UPS's largest customer but not its most profitable, and that its margin is very dilutive to the US business.\n\nAmazon now runs its own delivery network, which gives it bargaining power with carriers. UPS chose to shrink the relationship rather than keep carrying low-margin volume.", "sources": [{"url": "https://www.supplychaindive.com/news/ups-amazon-volume-reduction-q4-2024-earnings/738749/", "label": "Supply Chain Dive, UPS to cut Amazon volume by more than half"}, {"url": "https://www.nasdaq.com/press-release/pitney-bowes-parcel-shipping-index-us-carrier-disruption-increasing-and-thats-good", "label": "Pitney Bowes Parcel Shipping Index"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the chain in order.", "steps": ["Amazon builds its own delivery network", "Amazon gains bargaining power with carriers", "Amazon volume becomes low margin for UPS", "UPS decides to cut Amazon volume by more than half"], "explanation": "A customer with its own network can push prices down. UPS answered by shrinking the volume."}, "numbers": {"kind": "numberSense", "prompt": "What share of UPS revenue came from Amazon in 2024?", "min": 0, "max": 40, "value": 11.8, "unit": "%", "explanation": "Amazon was 11.8% of UPS revenue, and 20% to 25% of its US network volume."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A carrier interviewer asks how you would think about its biggest customer.", "prompt": "What shows you learned from UPS and Amazon?", "options": ["Say customers never become competitors", "Ask about its margin, not just its volume", "Say bigger customers are always better"], "correctIndex": 1, "consequences": ["Amazon became a rival delivery network.", "You show that volume and profit are different things.", "UPS's biggest customer was not its most profitable."], "explanation": "UPS's largest customer diluted its margins. Volume alone can mislead."}, "proReasoning": "Strong candidates ask about customer concentration and margin together.", "commonMistake": "Praising a big account without asking what it earns.", "mentalModel": "Ask what the biggest customer earns you."}, "invest": {"call": {"kind": "theCall", "situation": "UPS will shed more than half of its Amazon volume by late 2026.", "prompt": "What should an investor watch?", "options": ["Whether total volume grows this year", "Whether Amazon's share price rises soon", "Whether margins rise as cheap volume leaves"], "correctIndex": 2, "consequences": ["Volume is expected to fall by design.", "Amazon's stock does not show UPS's results.", "You track the reason UPS made the move."], "explanation": "UPS is trading volume for margin. The test is whether margins improve as Amazon volume leaves."}, "proReasoning": "Investors judge a strategy by the metric it targets. Here that is margin, not volume.", "commonMistake": "Reading lower volume as failure when it is the plan.", "mentalModel": "Judge the plan by what it aims to fix."}, "build_startup": {"call": {"kind": "theCall", "situation": "UPS will free up a large share of network capacity as Amazon volume leaves.", "prompt": "Where is the opening for a startup?", "options": ["Helping smaller shippers use carrier space", "Building a rival to Amazon's network", "Selling more delivery volume to Amazon"], "correctIndex": 0, "consequences": ["Freed capacity needs new customers, often smaller shippers.", "Matching Amazon's network takes vast capital.", "Amazon is moving volume away from carriers."], "explanation": "Carriers will want new, smaller customers to fill space. Tools that connect them help."}, "proReasoning": "Founders look for capacity that suddenly needs buyers.", "commonMistake": "Chasing the giant instead of the gap it leaves.", "mentalModel": "Fill the space the giant leaves."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that UPS chose to deliver fewer packages for its biggest customer.", "prompt": "Why would it do that?", "options": ["Amazon stopped selling goods online", "Those packages earned too little for it", "UPS ran out of trucks and drivers"], "correctIndex": 1, "consequences": ["Amazon keeps growing its own deliveries.", "You see that not all volume is good volume.", "UPS has a huge owned network."], "explanation": "Amazon's volume was low margin. UPS chose profit over size."}, "proReasoning": "Ask what each customer earns, not just how big it is.", "commonMistake": "Assuming every company wants as much business as possible.", "mentalModel": "Not all volume is worth having."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b6648d8065d1$ml$]::text[]),
($ml$ddab34e3-aae2-58e8-bf1f-d177d9dab362$ml$::uuid, $ml$logistics$ml$, 3, 2, $ml${"id": "logistics-d3-c2", "title": "The broker in the parcel fight", "lessonTitle": "Who holds the power in delivery", "slot": 2, "type": "connect", "brief": {"headline": "In 2024 Amazon delivered 6.3 billion US parcels, 28% of the market. C.H. Robinson works with over 450,000 providers while owning little equipment.", "kicker": "Connect day 2 and day 3: asset-light players and network power.", "fullText": "Day 2 showed that brokers sell access to capacity while carriers own it. Day 3 shows that control of a network shifts power.\n\nUSPS delivered 31% of US parcels in 2024, Amazon 28%, UPS 21% and FedEx 17%, out of 22.37 billion. Big shippers that build their own networks gain bargaining power. Smaller shippers without networks lean on carriers and brokers to find capacity.", "sources": [{"url": "https://www.nasdaq.com/press-release/pitney-bowes-parcel-shipping-index-us-carrier-disruption-increasing-and-thats-good", "label": "Pitney Bowes Parcel Shipping Index"}, {"url": "https://www.sec.gov/Archives/edgar/data/1043277/000104327726000009/chrw-20251231.htm", "label": "C. H. Robinson 10-K, 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Who has more power over delivery prices?", "left": {"name": "A shipper with its own network", "note": "Can move volume in-house"}, "right": {"name": "A shipper with no network", "note": "Must use carriers"}, "correctIndex": 0, "explanation": "A shipper that can deliver itself can walk away from carriers, which gives it bargaining power."}, "numbers": {"kind": "numberSense", "prompt": "How many billion US parcels were shipped in 2024?", "min": 0, "max": 40, "value": 22.4, "unit": "B", "explanation": "About 22.37 billion parcels, up 3.4%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You can join a broker that serves mid-size shippers or a big retailer's own network.", "prompt": "What is the key difference in your work?", "options": ["Both jobs are really the same work in practice", "The retailer only hires truck drivers", "The broker sells capacity; the retailer runs it"], "correctIndex": 2, "consequences": ["Selling capacity and running a network differ.", "Networks need planners, analysts and managers too.", "You see one role sells access while the other operates."], "explanation": "Brokers sell access to capacity. A retailer's network operates its own deliveries."}, "proReasoning": "Candidates who know which side of the network they join prepare for the right job.", "commonMistake": "Assuming every logistics job is the same.", "mentalModel": "Know which side of the network you join."}, "invest": {"call": {"kind": "theCall", "situation": "Amazon delivers 28% of US parcels, more than UPS or FedEx.", "prompt": "What does that mean for carriers' pricing power?", "options": ["It weakens it with large shippers", "It strengthens it with everyone", "It has no effect"], "correctIndex": 0, "consequences": ["Big shippers can now threaten to deliver themselves.", "A large shipper turned rival weakens carriers on price.", "A 28% share changes bargaining."], "explanation": "When customers can deliver themselves, carriers lose pricing power with them."}, "proReasoning": "Investors watch whether big customers are building their own networks.", "commonMistake": "Ignoring that customers can become competitors.", "mentalModel": "Watch for customers who can deliver themselves."}, "build_startup": {"call": {"kind": "theCall", "situation": "Smaller shippers have no network of their own and depend on carriers.", "prompt": "What product meets their need?", "options": ["Discounts only for the largest shippers", "A tool that compares and books several carriers", "A private parcel network built from scratch"], "correctIndex": 1, "consequences": ["Large shippers already have bargaining power.", "You widen the options of shippers with little power.", "Building a network needs vast capital."], "explanation": "Smaller shippers gain power by having more choices. Comparison and booking tools give them that."}, "proReasoning": "Founders often serve the side of a market with the least power.", "commonMistake": "Building for the big players who need you least.", "mentalModel": "Give the weak side more options."}, "curiosity": {"call": {"kind": "theCall", "situation": "You learn USPS still delivers more US parcels than Amazon.", "prompt": "What explains its lead?", "options": ["It owns the most retail stores", "It charges far less than everyone", "It reaches every address in the country"], "correctIndex": 2, "consequences": ["Its edge is the delivery network, not stores.", "It delivered 6.9 billion parcels in 2024.", "Universal reach makes it the default for many parcels."], "explanation": "USPS delivered 6.9 billion parcels, 31%, using a network that reaches every address."}, "proReasoning": "In delivery, the reach of the network decides who wins volume.", "commonMistake": "Thinking only private companies matter in parcels.", "mentalModel": "Reach is power in delivery."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b5fb9390ef15$ml$]::text[]),
($ml$d6b79e76-b30c-59e5-bfec-a50afc69294b$ml$::uuid, $ml$logistics$ml$, 3, 3, $ml${"id": "logistics-d3-c3", "title": "When your top customer leaves", "lessonTitle": "Who holds the power in delivery", "slot": 3, "type": "decide", "brief": {"headline": "You run a regional delivery carrier. Your largest customer, 35% of volume, says it will build its own network next year.", "kicker": "Decide: how do you respond when a customer becomes a rival?", "fullText": "Amazon's 28% share of US parcels shows how a big customer can become a competitor. Shippers with their own networks gain bargaining power with carriers, and losing one large account can reshape a carrier's business.\n\nYou have about a year before the volume starts to leave. Your trucks, drivers and sorting space were sized for it.", "sources": [{"url": "https://www.nasdaq.com/press-release/pitney-bowes-parcel-shipping-index-us-carrier-disruption-increasing-and-thats-good", "label": "Pitney Bowes Parcel Shipping Index"}, {"url": "https://www.supplychaindive.com/news/ups-amazon-volume-reduction-q4-2024-earnings/738749/", "label": "Supply Chain Dive, UPS to cut Amazon volume by more than half"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What is your best first move?", "options": ["Win more customers so no one is 35% of volume", "Cut prices to keep the leaving customer at any cost", "Do nothing until the volume actually leaves"], "correctIndex": 0, "explanation": "Spreading volume across customers reduces the power any one customer holds over you."}, "numbers": {"kind": "numberSense", "prompt": "What share of UPS's US network volume was tied to Amazon, at the top of the range?", "min": 0, "max": 40, "value": 25, "unit": "%", "explanation": "About 20% to 25% of UPS's US volume was tied to Amazon."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You lead sales at the carrier. The CEO asks for a plan within a month.", "prompt": "What do you put first?", "options": ["A pipeline of new customers by size and lane", "A price cut for the departing customer", "A plan to buy more trucks and vans"], "correctIndex": 0, "consequences": ["You replace the volume before it leaves.", "Price cuts rarely stop a customer building its own network.", "More trucks deepen the problem."], "explanation": "The fix is new volume from many customers, starting now."}, "proReasoning": "Strong sales leads turn a loss into a diversification plan with targets.", "commonMistake": "Spending the year trying to change the customer's mind.", "mentalModel": "Replace the volume before it leaves."}, "invest": {"call": {"kind": "theCall", "situation": "A carrier you hold gets 35% of volume from one customer building its own network.", "prompt": "What do you watch over the next year?", "options": ["The carrier's logo redesign", "How fast new customers replace the volume", "Whether the customer's new network is late"], "correctIndex": 1, "consequences": ["Branding does not fix concentration.", "You track the real recovery path.", "A delay only postpones the loss."], "explanation": "The risk is concentration. Progress means new customers, not hoping the old one fails."}, "proReasoning": "Investors track customer concentration as a core risk.", "commonMistake": "Betting on the customer's project failing.", "mentalModel": "Track the replacement, not the departure."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your delivery startup has one huge customer at 35% of volume.", "prompt": "What lesson do you take from UPS and Amazon?", "options": ["Grow that customer to 60% for scale", "Concentration only matters for big firms", "Diversify before your top customer can leave"], "correctIndex": 2, "consequences": ["Deeper reliance raises the risk.", "Concentration can sink a startup fast.", "You reduce the power one customer holds."], "explanation": "One customer at 35% can reshape your business when it leaves. Spread the risk early."}, "proReasoning": "Founders treat customer concentration as a risk to manage from day one.", "commonMistake": "Celebrating the big account without planning for its exit.", "mentalModel": "No customer should hold your future."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why a customer would build its own delivery network.", "prompt": "What drives that decision?", "options": ["Control over cost and service at its scale", "Carriers refuse to deliver for it", "Building a network is cheap and quick"], "correctIndex": 0, "consequences": ["You see that scale makes owning worthwhile.", "Carriers usually want the volume.", "Networks need large investment."], "explanation": "At enough volume, owning delivery gives control over cost and service."}, "proReasoning": "Scale changes the build-or-buy math.", "commonMistake": "Thinking only carriers can run delivery.", "mentalModel": "Scale makes owning worth it."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6d3e5439726c$ml$]::text[]),
($ml$010e19f2-449e-5797-a6ac-04a718d23232$ml$::uuid, $ml$logistics$ml$, 4, 1, $ml${"id": "logistics-d4-c1", "title": "Fewer loads, flat spending", "lessonTitle": "The numbers that move freight", "slot": 1, "type": "apply", "brief": {"headline": "The Cass shipments index fell 6.9% from a year earlier in July 2025, its largest drop since January. Freight spending rose 0.4% over the same period.", "kicker": "Apply the rule: read volume and price separately.", "fullText": "The Cass Freight Index tracks shipments and spending across a large base of shippers. In July 2025, shipments fell 6.9% year over year, extending a run of declines that FreightWaves put at 30 months.\n\nExpenditures, the money shippers spent on freight, rose 0.4% year over year. That was the fourth straight positive month after more than two years of declines. Fewer loads at slightly higher total cost points to firmer rates per load.", "sources": [{"url": "https://www.freightwaves.com/?p=562614", "label": "FreightWaves, freight shipment decline streak extends to 30 months"}, {"url": "https://trucking.org/news-insights/ata-releases-latest-edition-american-trucking-trends-0", "label": "ATA, American Trucking Trends 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Shipments fall 6.9% but spending rises 0.4%. What does that suggest?", "options": ["Each load is costing shippers a bit more", "Freight volume is growing again fast", "Shippers are paying less for each load"], "correctIndex": 0, "explanation": "Total spending held up while loads fell, so the cost per load must have risen."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did the Cass shipments index fall year over year in July 2025?", "min": 0, "max": 15, "value": 6.9, "unit": "%", "explanation": "It fell 6.9%, the largest decline since January."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You start as a freight analyst. Your manager asks for one line on the July Cass data.", "prompt": "What do you write?", "options": ["Freight is booming across every mode now", "Spending fell as fast as shipments did", "Loads are down, but price per load is firming"], "correctIndex": 2, "consequences": ["Shipments fell 6.9%; that is not a boom.", "Spending rose 0.4% while shipments fell.", "You split volume from price, which is the useful read."], "explanation": "Shipments fell while spending rose slightly. Volume and price told different stories."}, "proReasoning": "Good analysts report volume and price as two signals. Mixing them hides the turn.", "commonMistake": "Reading one index as the whole market.", "mentalModel": "Volume and price are two signals."}, "invest": {"call": {"kind": "theCall", "situation": "Shipments keep falling, but freight spending has risen four months in a row.", "prompt": "What might an investor in trucking stocks watch next?", "options": ["Whether rates keep rising as volume stabilizes", "Whether shipments fall to zero this year", "Whether diesel prices fall next week"], "correctIndex": 0, "consequences": ["Firmer rates with steady volume would help carriers' margins.", "Freight demand does not fall to zero.", "One week of fuel prices says little about the cycle."], "explanation": "Rising spending on fewer loads hints at firmer pricing. If volume steadies, carrier margins can improve."}, "proReasoning": "Investors look for the turn in rates before volume. Pricing often moves first.", "commonMistake": "Waiting for volume to grow before paying attention.", "mentalModel": "Price can turn before volume does."}, "build_startup": {"call": {"kind": "theCall", "situation": "Shippers are moving fewer loads but paying a little more for each one.", "prompt": "What product pitch fits this moment?", "options": ["Sell carriers tools to haul more loads", "Help shippers cut cost per load with better bids", "Promise shippers far more trucks than they need"], "correctIndex": 1, "consequences": ["Carriers face fewer loads, not more.", "You target the cost that is rising for shippers.", "Shippers need fewer trucks, not more."], "explanation": "When cost per load rises, shippers want tools that lower it."}, "proReasoning": "Founders pitch to the pain the data shows right now.", "commonMistake": "Pitching growth tools in a falling market.", "mentalModel": "Sell to the cost that is rising."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that freight shipments fell for months while spending started to rise.", "prompt": "How can both be true?", "options": ["Shippers started moving more loads", "The two numbers measure the same thing", "Each load got more expensive to move"], "correctIndex": 2, "consequences": ["Shipments fell, they did not rise.", "One counts loads, the other counts dollars.", "You see that total spend is loads times price."], "explanation": "Spending equals loads times price per load. Fewer loads at higher prices can lift spending."}, "proReasoning": "Break a total into quantity and price. It explains most freight headlines.", "commonMistake": "Assuming spending and volume always move together.", "mentalModel": "Total spend is loads times price."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b104a16a1a94$ml$]::text[]),
($ml$c8a90e4a-a98f-5936-a778-52b3e456cf78$ml$::uuid, $ml$logistics$ml$, 4, 2, $ml${"id": "logistics-d4-c2", "title": "Same loads, less revenue", "lessonTitle": "The numbers that move freight", "slot": 2, "type": "connect", "brief": {"headline": "US trucks moved about 11.27 billion tons in 2024, down from 11.41 billion. Trucking revenue fell to about $906 billion from $1.004 trillion.", "kicker": "Connect day 2 and day 4: fixed costs meet falling revenue.", "fullText": "Day 2 showed that asset-heavy carriers own trucks and employ drivers, so their costs do not shrink when freight softens. Day 4 shows what 2024 looked like.\n\nTonnage barely moved, down about 1%, while revenue fell about 10%. Trucks still carried more than 72% of US freight tonnage, with about 3.58 million truck drivers. Carriers with owned fleets had nearly the same work and a lot less money.", "sources": [{"url": "https://trucking.org/news-insights/ata-releases-latest-edition-american-trucking-trends-0", "label": "ATA, American Trucking Trends 2025"}, {"url": "https://www.sec.gov/Archives/edgar/data/728535/000143774926005294/jbht20251231_10k.htm", "label": "J. B. Hunt 10-K, 2025"}, {"url": "https://www.sec.gov/Archives/edgar/data/1043277/000104327726000009/chrw-20251231.htm", "label": "C. H. Robinson 10-K, 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the chain in order.", "steps": ["Rates fall while tonnage holds steady", "Trucking revenue drops about 10%", "Owned trucks and wages still cost the same", "Asset-heavy carriers see margins squeezed"], "explanation": "When revenue falls but fixed costs stay, carriers that own their capacity feel it most."}, "numbers": {"kind": "numberSense", "prompt": "How many billion dollars of revenue did US trucking earn in 2024?", "min": 0, "max": 1200, "value": 906, "unit": "B", "explanation": "About $906 billion, down from $1.004 trillion in 2023."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join an asset-heavy carrier in a year like 2024.", "prompt": "What will management focus on most?", "options": ["Keeping trucks loaded and costs per mile down", "Buying many more trucks right away", "Raising prices well above the market rate"], "correctIndex": 0, "consequences": ["You see where margin comes from when rates fall.", "More trucks add fixed cost in a soft market.", "Shippers can switch carriers if prices jump."], "explanation": "With revenue down and costs fixed, every empty mile hurts. Utilization becomes the priority."}, "proReasoning": "People who thrive at carriers in soft markets focus on use of assets and cost control.", "commonMistake": "Expecting growth projects in a down year.", "mentalModel": "Fill the trucks you already own."}, "invest": {"call": {"kind": "theCall", "situation": "Tonnage fell about 1% in 2024 but trucking revenue fell about 10%.", "prompt": "What does that gap tell an investor?", "options": ["Trucks lost share to other modes", "Prices, not volume, drove the drop", "Demand for trucking collapsed"], "correctIndex": 1, "consequences": ["Trucks still carried more than 72% of tonnage.", "You see the drop came mainly from lower rates.", "Tonnage barely moved."], "explanation": "Tons held steady while revenue fell. Lower rates explain most of the decline."}, "proReasoning": "Investors separate volume from price to see what really changed.", "commonMistake": "Calling a pricing slump a demand collapse.", "mentalModel": "Ask whether volume or price moved."}, "build_startup": {"call": {"kind": "theCall", "situation": "Carriers have about the same tonnage but about 10% less revenue.", "prompt": "What do carriers want to buy now?", "options": ["Software to plan a big fleet expansion", "Ads to find many new truck drivers", "Tools that cut cost per mile"], "correctIndex": 2, "consequences": ["Few carriers expand in a squeeze.", "Hiring is not the urgent problem in a slump.", "You sell savings when revenue is under pressure."], "explanation": "In a squeeze, carriers buy what saves money fast."}, "proReasoning": "Founders time their pitch to the cycle. Savings sell in downturns.", "commonMistake": "Selling growth tools when buyers are cutting costs.", "mentalModel": "In a squeeze, sell savings."}, "curiosity": {"call": {"kind": "theCall", "situation": "You learn trucks carried almost the same tonnage but earned far less.", "prompt": "Why would that happen?", "options": ["Too many trucks chased the same freight", "Trucks suddenly got far more efficient", "Shippers stopped paying their bills"], "correctIndex": 0, "consequences": ["You see that extra capacity pushes rates down.", "Efficiency changes slowly over years.", "Nothing points to unpaid bills."], "explanation": "When capacity outruns demand, carriers compete on price and revenue falls."}, "proReasoning": "Ask whether supply or demand changed. In 2024 it was price pressure.", "commonMistake": "Thinking less revenue always means less work.", "mentalModel": "Extra capacity pushes prices down."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9a701a99850c$ml$]::text[]),
($ml$fc1d564c-0b04-5ee6-b649-e1da6a102003$ml$::uuid, $ml$logistics$ml$, 4, 3, $ml${"id": "logistics-d4-c3", "title": "Hire drivers in a soft year?", "lessonTitle": "The numbers that move freight", "slot": 3, "type": "decide", "brief": {"headline": "You run a 300-truck carrier. Revenue fell about 10% last year while your loads held steady, and your best driver recruiter asks to hire 40 drivers.", "kicker": "Decide: grow capacity while rates are weak?", "fullText": "In 2024 US trucks moved about 11.27 billion tons, barely down, while trucking revenue fell to about $906 billion from $1.004 trillion. The US had about 3.58 million truck drivers.\n\nYour loads look like the market: steady volume at lower prices. Forty more drivers would let you run more trucks, but each added truck brings costs that stay even if rates stay low.", "sources": [{"url": "https://trucking.org/news-insights/ata-releases-latest-edition-american-trucking-trends-0", "label": "ATA, American Trucking Trends 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Which signal matters more before adding capacity?", "left": {"name": "Rates per load", "note": "Fell about 10% last year"}, "right": {"name": "Tons hauled", "note": "Held almost steady"}, "correctIndex": 0, "explanation": "Steady loads at falling rates means added trucks would earn less, not more."}, "numbers": {"kind": "numberSense", "prompt": "How many million truck drivers worked in the US in 2024?", "min": 0, "max": 6, "value": 3.6, "unit": "M", "explanation": "About 3.58 million truck drivers."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You lead recruiting. The CEO says no new hires until rates recover.", "prompt": "What do you work on instead?", "options": ["Moving to sales to sell more loads", "Keeping the drivers you already have", "Hiring anyway to beat the next upturn"], "correctIndex": 1, "consequences": ["Switching jobs skips the task in front of you.", "Keeping good drivers saves cost and keeps capacity ready.", "Hiring against the CEO's plan raises fixed costs."], "explanation": "Retention protects capacity without adding cost in a soft market."}, "proReasoning": "Good recruiters shift to retention when growth pauses.", "commonMistake": "Treating recruiting as only hiring new people.", "mentalModel": "Keep the drivers you have."}, "invest": {"call": {"kind": "theCall", "situation": "A carrier you hold plans to add 40 drivers while rates are still falling.", "prompt": "What do you ask management?", "options": ["How many new hires will they post online?", "Whether drivers like the new truck colors", "What rates do the new trucks need to pay off?"], "correctIndex": 2, "consequences": ["Posting numbers says nothing about returns.", "Truck colors do not change returns.", "You test the plan against current pricing."], "explanation": "Adding trucks makes sense only if rates cover their cost. Ask for that number."}, "proReasoning": "Investors ask what each new asset must earn to pay back.", "commonMistake": "Cheering growth without asking about returns.", "mentalModel": "Growth must pay at today's prices."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a small carrier and could add trucks cheaply in a soft market.", "prompt": "What is the careful move?", "options": ["Add trucks only against signed contract volume", "Add trucks now and hunt for loads later on", "Sell off the trucks you already run today"], "correctIndex": 0, "consequences": ["You add cost only where revenue is already promised.", "Empty trucks drain cash fast.", "Selling everything ends the business."], "explanation": "Signed volume covers the new costs. Speculative trucks may sit idle."}, "proReasoning": "Founders tie new capacity to committed demand.", "commonMistake": "Buying trucks because they are cheap, not because loads are waiting.", "mentalModel": "Add capacity behind signed volume."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why a carrier would not hire when it has 300 trucks running.", "prompt": "What holds it back?", "options": ["Trucks are now banned on highways", "Lower rates mean new trucks may not pay", "There are no drivers anywhere in the US"], "correctIndex": 1, "consequences": ["Trucks still haul most freight.", "You see the link between price and growth.", "The US had about 3.58 million drivers."], "explanation": "Revenue fell while costs stayed. More trucks at weak rates can lose money."}, "proReasoning": "Growth depends on price, not only on demand.", "commonMistake": "Thinking more loads always justify more trucks.", "mentalModel": "Price decides if growth pays."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6ac591b0f4ca$ml$]::text[]),
($ml$0d5d8bd1-0687-5265-a3e8-43ce4cf484ed$ml$::uuid, $ml$logistics$ml$, 5, 1, $ml${"id": "logistics-d5-c1", "title": "Testing a pause on the clock", "lessonTitle": "The rule that limits every truck's day", "slot": 1, "type": "apply", "brief": {"headline": "FMCSA plans two pilot programs to test more flexible driver hours. One lets drivers pause the 14-hour window for 30 minutes to 3 hours.", "kicker": "Apply the rule: hours rules set the pace of freight.", "fullText": "The pilots were announced in June 2025 and published in the Federal Register in September 2025. The Split Duty Period pilot tests pausing the 14-hour window. The Flexible Sleeper Berth pilot tests 6/4 and 5/5 splits, beyond today's 8/2 and 7/3 options.\n\nEach pilot plans about 256 CDL holders, more than 500 drivers in total. Each driver takes part for four months, one as a baseline and three under the pilot, and the program runs for about three years.", "sources": [{"url": "https://www.truckinginfo.com/news/fmcsa-to-pilot-14-hour-clock-pause-split-sleeper-options-for-truck-drivers", "label": "HDT, FMCSA to pilot a 14-hour clock pause and split sleeper options"}, {"url": "https://www.fmcsa.dot.gov/regulations/hours-service/summary-hours-service-regulations", "label": "FMCSA, hours of service summary"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Today a 30-minute break does not extend the 14-hour window.", "One pilot tests a 6/4 sleeper berth split.", "The pilots already apply to every US truck driver."], "fakeIndex": 2, "explanation": "The pilots cover about 500 drivers in total, not every driver."}, "numbers": {"kind": "numberSense", "prompt": "How many CDL holders does each pilot plan to enroll?", "min": 0, "max": 600, "value": 256, "unit": "", "explanation": "About 256 per pilot, more than 500 in total."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work in fleet safety. A driver asks if the 14-hour pause is now legal for everyone.", "prompt": "What do you tell them?", "options": ["Only drivers enrolled in the pilot can use it", "Yes, every driver can pause the clock now", "Breaks have always paused the 14-hour clock"], "correctIndex": 0, "consequences": ["You keep the driver within today's rules.", "The pause is a test, not a rule change.", "Breaks do not extend the 14-hour window today."], "explanation": "The pause applies only inside the pilot. Everyone else follows the standard rules."}, "proReasoning": "Safety staff separate proposals and pilots from rules in force.", "commonMistake": "Treating a pilot as if it were already law.", "mentalModel": "A pilot is not a rule change."}, "invest": {"call": {"kind": "theCall", "situation": "FMCSA is testing a pause on the 14-hour window that could add usable hours.", "prompt": "How should an investor treat this news?", "options": ["As proof the rules will never change", "As a slow, uncertain change years away", "As an instant boost to carrier profits"], "correctIndex": 1, "consequences": ["A pilot shows the rules are being tested.", "The pilot runs about three years before any rule.", "Nothing changes for most drivers today."], "explanation": "Pilots gather data over years. Any rule change would come later, if at all."}, "proReasoning": "Investors price regulatory change by its timeline, not its headline.", "commonMistake": "Pricing a pilot as if it were final.", "mentalModel": "Price the timeline, not the headline."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build electronic logging software for fleets.", "prompt": "What should you do about the pilots?", "options": ["Switch every customer to the new rules now", "Ignore the pilots until there is a final rule", "Prepare to track pilot rules for enrolled drivers"], "correctIndex": 2, "consequences": ["Most drivers must still follow today's rules.", "You could miss early customers in the pilot.", "You serve pilot fleets without breaking rules for others."], "explanation": "Enrolled drivers need logs that handle pilot rules. Everyone else needs today's rules."}, "proReasoning": "Founders ready their product for rule changes early, but only switch on what is legal.", "commonMistake": "Treating a test as a new standard for all users.", "mentalModel": "Build for the pilot, ship to the enrolled."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why a 30-minute pause matters so much to truckers.", "prompt": "Why does it?", "options": ["Today, waiting time eats into a fixed 14 hours", "Drivers are paid more for each pause they take", "It lets them drive 20 hours a day"], "correctIndex": 0, "consequences": ["You see how waiting uses up the driving window.", "The pilot is about time, not pay rates.", "The 11-hour driving limit still applies."], "explanation": "Today the 14-hour window keeps running during breaks and waits. A pause would save usable time."}, "proReasoning": "Small rule details can decide how far freight moves in a day.", "commonMistake": "Assuming hours rules only limit driving time.", "mentalModel": "Waiting time is lost time today."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:cee79a27783e$ml$]::text[]),
($ml$8f6b3d6d-adc4-55cb-a5da-c71d68a59bd5$ml$::uuid, $ml$logistics$ml$, 5, 2, $ml${"id": "logistics-d5-c2", "title": "Most freight, fixed hours", "lessonTitle": "The rule that limits every truck's day", "slot": 2, "type": "connect", "brief": {"headline": "Trucks carry more than 72% of US freight tonnage. Every one of those drivers can drive at most 11 hours, within a 14-hour window, after 10 hours off.", "kicker": "Connect day 4 and day 5: big volume, fixed clock.", "fullText": "Day 4 showed that trucks move most US freight, with about 3.58 million drivers. Day 5 adds the clock: 11 hours of driving after 10 consecutive hours off, no driving after the 14th hour, a 30-minute break after 8 hours of driving, and weekly limits of 60 or 70 hours.\n\nBecause trucks carry so much freight, the same hours limits shape delivery times across the whole supply chain.", "sources": [{"url": "https://trucking.org/news-insights/ata-releases-latest-edition-american-trucking-trends-0", "label": "ATA, American Trucking Trends 2025"}, {"url": "https://www.fmcsa.dot.gov/regulations/hours-service/summary-hours-service-regulations", "label": "FMCSA, hours of service summary"}]}, "evidence": {"kind": "sortSignal", "prompt": "Real hours rule or not?", "buckets": ["Real rule", "Not a rule"], "items": [{"text": "11 hours of driving after 10 off", "bucket": 0}, {"text": "No driving after the 14th hour", "bucket": 0}, {"text": "34-hour restart of the weekly clock", "bucket": 0}, {"text": "Breaks extend the 14-hour window", "bucket": 1}, {"text": "No weekly limit on hours", "bucket": 1}], "explanation": "Breaks do not extend the window, and drivers face 60 or 70 hour weekly limits."}, "numbers": {"kind": "numberSense", "prompt": "After how many hours of driving must a driver take a 30-minute break?", "min": 0, "max": 14, "value": 8, "unit": "hours", "explanation": "A 30-minute break is required after 8 cumulative hours of driving."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You plan routes for a shipper. A store wants a delivery 900 miles away by tomorrow.", "prompt": "What do you check first?", "options": ["Whether the truck has enough fuel", "Whether one driver can legally make it in time", "Whether the store will pay for driver overtime"], "correctIndex": 1, "consequences": ["Fuel matters less than the legal limit.", "You test the plan against the hours clock.", "Hours limits are rules, not overtime choices."], "explanation": "A solo driver gets 11 driving hours before a 10-hour rest. Long runs can need two drivers."}, "proReasoning": "Planners check hours first because they cap what any route can do.", "commonMistake": "Promising delivery dates before checking driver hours.", "mentalModel": "Check the clock before you promise."}, "invest": {"call": {"kind": "theCall", "situation": "Trucks carry more than 72% of US tonnage under fixed hours limits.", "prompt": "Why do investors care about hours rules?", "options": ["They set the price of diesel", "They only matter to small carriers", "They cap how much work each truck can do"], "correctIndex": 2, "consequences": ["Fuel prices come from energy markets.", "Every carrier faces the same limits.", "You link rules to capacity and pricing."], "explanation": "Hours limits cap how many miles a truck and driver can run. That shapes capacity and rates."}, "proReasoning": "Investors watch rule changes as changes to effective capacity.", "commonMistake": "Treating hours rules as paperwork.", "mentalModel": "Rules on hours are rules on capacity."}, "build_startup": {"call": {"kind": "theCall", "situation": "Most freight moves by truck, and every driver works within a 14-hour window.", "prompt": "Where can software help most?", "options": ["Cutting time drivers lose waiting at docks", "Making trucks legally drive 18 hours", "Removing the need for weekly limits"], "correctIndex": 0, "consequences": ["You give drivers back usable hours inside the rules.", "Software cannot change legal limits.", "Weekly limits are set by regulation."], "explanation": "Waiting at docks uses up the 14-hour window. Saving that time adds real capacity."}, "proReasoning": "Founders work within rules and attack wasted time.", "commonMistake": "Building around rules you hope will change.", "mentalModel": "Save time inside the rules."}, "curiosity": {"call": {"kind": "theCall", "situation": "You learn a 30-minute break does not extend a driver's 14-hour window.", "prompt": "What does that mean for a driver stuck at a dock?", "options": ["Waiting never counts against the driver", "Waiting time cuts into the hours left to drive", "The driver gets extra hours to make it up"], "correctIndex": 1, "consequences": ["The window keeps running during waits.", "You see why long waits cost freight time.", "Breaks do not add hours."], "explanation": "The 14-hour window keeps running. Hours spent waiting are hours not driving."}, "proReasoning": "Follow the clock to see why delays spread.", "commonMistake": "Thinking a stop pauses the day.", "mentalModel": "The clock keeps running."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f9529db91bd7$ml$]::text[]),
($ml$3953c7f6-904c-5f7b-abac-8760c88d1838$ml$::uuid, $ml$logistics$ml$, 5, 3, $ml${"id": "logistics-d5-c3", "title": "A run too long for one driver", "lessonTitle": "The rule that limits every truck's day", "slot": 3, "type": "decide", "brief": {"headline": "You run dispatch for a carrier. A customer needs a load delivered that takes about 15 hours of driving, as fast as possible.", "kicker": "Decide: how do you move it within the rules?", "fullText": "A solo driver can drive at most 11 hours after 10 consecutive hours off and cannot drive after the 14th hour on duty. A 30-minute break is due after 8 hours of driving.\n\nA 15-hour run is beyond one driver's daily limit. You can send a solo driver with a 10-hour rest on the way, use a team of two drivers, or relay the load between drivers.", "sources": [{"url": "https://www.fmcsa.dot.gov/regulations/hours-service/summary-hours-service-regulations", "label": "FMCSA, hours of service summary"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What is the fastest legal way to move a 15-hour run?", "options": ["One driver who takes longer breaks", "A team of two drivers taking turns", "One driver who skips the 10-hour rest"], "correctIndex": 1, "explanation": "A team lets one driver rest while the other drives. Skipping rest is illegal, and breaks do not add hours."}, "numbers": {"kind": "numberSense", "prompt": "How many hours off duty must come before a new 11-hour driving period?", "min": 0, "max": 24, "value": 10, "unit": "hours", "explanation": "A driver needs 10 consecutive hours off duty."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The customer pushes you to promise delivery in 16 hours with one driver.", "prompt": "What do you say?", "options": ["Promise it and let the driver find some way", "Tell the driver to log the hours as rest", "Offer a team or a later time; one driver cannot"], "correctIndex": 2, "consequences": ["That pushes the driver to break the rules.", "False logs are a serious violation.", "You protect the driver and the company."], "explanation": "One driver cannot drive 15 hours in one stretch. Offer a legal option."}, "proReasoning": "Good dispatchers give customers legal choices with honest times.", "commonMistake": "Promising what only a rule break can deliver.", "mentalModel": "Offer the legal options."}, "invest": {"call": {"kind": "theCall", "situation": "A carrier advertises fast long-haul service using team drivers.", "prompt": "What should an investor understand about that service?", "options": ["Two drivers per truck cost more but move faster", "Teams are cheaper to run than solo drivers", "Teams avoid the hours rules entirely"], "correctIndex": 0, "consequences": ["You see the trade-off between speed and cost.", "Paying two drivers costs more.", "Each driver still follows the rules."], "explanation": "Teams keep a truck moving while one driver rests. Speed comes at a higher labor cost."}, "proReasoning": "Investors check whether premium service earns enough to cover its costs.", "commonMistake": "Assuming fast service is always profitable.", "mentalModel": "Speed costs more; check it pays."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a small carrier that wants to offer long, fast runs.", "prompt": "What is a smart first option to build?", "options": ["Promises of times you cannot keep", "A relay plan that swaps drivers on the way", "One driver per truck with no rest stops"], "correctIndex": 1, "consequences": ["Broken promises lose customers.", "Relays move freight farther while each driver stays legal.", "That breaks the hours rules."], "explanation": "Relays let freight keep moving without one driver exceeding limits."}, "proReasoning": "Founders design service around the rules, not around them.", "commonMistake": "Building a service that depends on breaking rules.", "mentalModel": "Design around the clock."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why some trucks carry two drivers.", "prompt": "What is the reason?", "options": ["Two drivers are required on every truck", "It lets them skip the weekly limits", "One rests while the other keeps driving"], "correctIndex": 2, "consequences": ["Most trucks have one driver.", "Weekly limits still apply to each.", "You see how teams beat the daily clock."], "explanation": "Teams take turns, so the truck keeps moving while each driver stays within limits."}, "proReasoning": "When a rule limits a person, add people to keep the asset moving.", "commonMistake": "Thinking teams exist for company only.", "mentalModel": "Rest one, drive one."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ed21ee3469b6$ml$]::text[]),
($ml$c3b34050-4a52-5625-8d25-a15b1f486299$ml$::uuid, $ml$logistics$ml$, 6, 1, $ml${"id": "logistics-d6-c1", "title": "Another digital broker sells", "lessonTitle": "The digital broker that crashed", "slot": 1, "type": "apply", "brief": {"headline": "In June 2024, digital freight broker Transfix sold its brokerage business to NFI. It kept its transportation management software.", "kicker": "Apply the rule: the cycle beats the software.", "fullText": "HDT reported that Transfix was felled by the freight recession: a two-year downturn, less investor interest and high interest rates.\n\nThe deal added more than 15,000 motor carriers to NFI's network. Transfix kept its TMS, a software product sold as a service, and pivoted to it. Like Convoy a year earlier, a well-funded digital broker could not escape the freight cycle.", "sources": [{"url": "https://www.truckinginfo.com/news/transfix-sells-brokerage-business-to-nfi-pivots-to-tms-offering", "label": "HDT, Transfix sells brokerage business to NFI"}, {"url": "https://techcrunch.com/2023/11/01/flexport-acquires-technology-of-former-digital-freight-unicorn-convoy", "label": "TechCrunch, Flexport acquires technology of former digital freight unicorn Convoy"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the chain in order.", "steps": ["Freight demand stays weak for two years", "Broker margins and investor interest shrink", "High interest rates make new funding harder", "Transfix sells its brokerage to NFI"], "explanation": "A long downturn plus costly money pushed the brokerage to sell."}, "numbers": {"kind": "numberSense", "prompt": "How many thousand motor carriers did the Transfix deal add to NFI?", "min": 0, "max": 40, "value": 15, "unit": "K", "explanation": "More than 15,000 motor carriers."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work at a digital freight startup in a long downturn.", "prompt": "What signal should worry you most?", "options": ["The office moves to a smaller floor", "Funding is drying up while margins shrink", "A rival launches a new app feature"], "correctIndex": 1, "consequences": ["Office moves are minor next to cash.", "You track the two things that sank Transfix's brokerage.", "Features did not decide the outcome."], "explanation": "Shrinking margins plus scarce funding pushed Transfix to sell."}, "proReasoning": "Staff at startups watch cash and margins more than product news.", "commonMistake": "Thinking better software protects a broker in a long slump.", "mentalModel": "Watch cash and margins."}, "invest": {"call": {"kind": "theCall", "situation": "Transfix sold its brokerage but kept its software business.", "prompt": "What does that split suggest?", "options": ["Software and brokerage were the same asset", "NFI wanted to stop running trucks", "The software had value apart from the brokerage"], "correctIndex": 2, "consequences": ["They were sold separately for a reason.", "NFI took on more carriers.", "You see the buyer and seller valued different parts."], "explanation": "NFI bought carriers and customers. Transfix kept the software to sell as a service."}, "proReasoning": "Investors look at which parts of a business survive a sale.", "commonMistake": "Valuing a digital broker as a pure software company.", "mentalModel": "See which part survives the sale."}, "build_startup": {"call": {"kind": "theCall", "situation": "You plan a digital broker with heavy venture funding.", "prompt": "What lesson do Convoy and Transfix teach?", "options": ["Plan to survive a long freight downturn", "Raise money and grow as fast as possible", "Software alone protects you from cycles"], "correctIndex": 0, "consequences": ["You build for the cycle, not just the boom.", "Fast growth can leave you exposed when freight turns.", "Both had strong software and still sold."], "explanation": "Both were well funded and still could not outrun the freight recession."}, "proReasoning": "Founders in cyclical markets plan for the worst year, not the best.", "commonMistake": "Assuming good technology beats the freight cycle.", "mentalModel": "Plan for the down year."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why a tech-driven broker would sell during a slump.", "prompt": "What drove the sale?", "options": ["Carriers refused to book loads on apps", "Weak freight, less funding, high rates", "The software it built stopped working"], "correctIndex": 1, "consequences": ["The deal added 15,000 carriers to NFI.", "You name the forces HDT reported.", "Transfix kept and sold its software."], "explanation": "HDT tied the sale to the freight recession, less investor interest and high interest rates."}, "proReasoning": "Ask what changed outside the company before blaming the product.", "commonMistake": "Assuming every startup failure is a product failure.", "mentalModel": "Look outside the company first."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:bf0e1358c5dc$ml$]::text[]),
($ml$f85c5748-136a-5ddd-b39a-6e54a286fede$ml$::uuid, $ml$logistics$ml$, 6, 2, $ml${"id": "logistics-d6-c2", "title": "Asset-light, cycle-heavy", "lessonTitle": "The digital broker that crashed", "slot": 2, "type": "connect", "brief": {"headline": "Convoy was valued at $3.8 billion in 2022 and shut down in late 2023. Flexport bought its technology but not its business or liabilities.", "kicker": "Connect day 2 and day 6: light assets, heavy cycles.", "fullText": "Day 2 showed that brokers sell access to trucks they do not own, which keeps capital needs low. Day 6 shows the risk: a broker lives on the spread between shipper and carrier rates, and that spread can vanish in a downturn.\n\nConvoy raised a $260 million round at a $3.8 billion valuation in 2022. Its software automated the carrier side for 98% of booked loads. That did not save it when the freight market turned.", "sources": [{"url": "https://techcrunch.com/2023/11/01/flexport-acquires-technology-of-former-digital-freight-unicorn-convoy", "label": "TechCrunch, Flexport acquires technology of former digital freight unicorn Convoy"}, {"url": "https://www.sec.gov/Archives/edgar/data/1043277/000104327726000009/chrw-20251231.htm", "label": "C. H. Robinson 10-K, 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "What sank Convoy?", "left": {"name": "The freight cycle", "note": "Margins and funding dried up"}, "right": {"name": "Weak software", "note": "Automation did not work"}, "correctIndex": 0, "explanation": "Its software automated the carrier side for 98% of loads. The cycle, not the code, sank it."}, "numbers": {"kind": "numberSense", "prompt": "At what valuation, in billion dollars, did Convoy raise money in 2022?", "min": 0, "max": 6, "value": 3.8, "unit": "B", "explanation": "Convoy was valued at $3.8 billion in a $260 million round."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You are offered a job at a fast-growing digital broker during a freight boom.", "prompt": "What do you ask before joining?", "options": ["How big the launch party will be this year", "Whether the app has a dark mode yet", "How much cash runway they have for a downturn"], "correctIndex": 2, "consequences": ["Parties say nothing about survival.", "Features did not save Convoy.", "You test whether they can survive the next slump."], "explanation": "Brokers face swings in margins. Runway decides who survives the down years."}, "proReasoning": "Smart candidates ask about runway at cyclical startups.", "commonMistake": "Joining for the valuation without asking about the cycle.", "mentalModel": "Ask about the runway."}, "invest": {"call": {"kind": "theCall", "situation": "A digital broker asks investors to value it like a software company.", "prompt": "What should an investor remember?", "options": ["Its income still rises and falls with freight", "Software firms never face any downturns", "Brokers own trucks that hold their value"], "correctIndex": 0, "consequences": ["You price the freight cycle into the valuation.", "Every business faces some cycle.", "Brokers own very little equipment."], "explanation": "A broker earns the spread on freight. That spread swings with the market."}, "proReasoning": "Investors value businesses by how they earn, not by their branding.", "commonMistake": "Paying software prices for freight income.", "mentalModel": "Value it by how it earns."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want to build a digital broker after Convoy's collapse.", "prompt": "What do you do differently?", "options": ["Spend heavily to win market share first", "Keep costs low enough to survive bad years", "Raise a bigger round than Convoy did"], "correctIndex": 1, "consequences": ["Heavy spending deepens losses in a slump.", "You build to last through the cycle.", "More money did not save Convoy."], "explanation": "A broker's spread can shrink fast. Low costs keep you alive until it recovers."}, "proReasoning": "Founders who outlast cycles keep costs flexible.", "commonMistake": "Assuming funding solves cyclical risk.", "mentalModel": "Stay small enough to survive."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why a company with great software could still fail.", "prompt": "What is the answer?", "options": ["Its software never worked at all", "It owned too many trucks", "The market it served turned against it"], "correctIndex": 2, "consequences": ["It automated 98% of the carrier side.", "Convoy was asset-light.", "You see that markets can beat good products."], "explanation": "Convoy's software worked, but freight margins and funding dried up."}, "proReasoning": "Good products can fail in bad markets.", "commonMistake": "Judging a failure only by its product.", "mentalModel": "Markets can beat products."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:15de8cba5366$ml$]::text[]),
($ml$1a8e730b-1535-5363-a120-d782db205075$ml$::uuid, $ml$logistics$ml$, 6, 3, $ml${"id": "logistics-d6-c3", "title": "Cut now or keep growing?", "lessonTitle": "The digital broker that crashed", "slot": 3, "type": "decide", "brief": {"headline": "You run a digital freight broker. Freight has been weak for a year, margins are thin, and you have 18 months of cash.", "kicker": "Decide: how do you get through the cycle?", "fullText": "Convoy was valued at $3.8 billion in 2022 and shut down in late 2023. Transfix sold its brokerage to NFI in 2024 after a two-year downturn, less investor interest and high interest rates.\n\nYour board is split. One side wants to keep growing to win share, the other wants to cut costs and stretch the runway.", "sources": [{"url": "https://techcrunch.com/2023/11/01/flexport-acquires-technology-of-former-digital-freight-unicorn-convoy", "label": "TechCrunch, Flexport acquires technology of former digital freight unicorn Convoy"}, {"url": "https://www.truckinginfo.com/news/transfix-sells-brokerage-business-to-nfi-pivots-to-tms-offering", "label": "HDT, Transfix sells brokerage business to NFI"}]}, "evidence": {"kind": "sortSignal", "prompt": "Helps you survive, or adds risk?", "buckets": ["Helps survive", "Adds risk"], "items": [{"text": "Cut costs to stretch runway", "bucket": 0}, {"text": "Focus on profitable lanes", "bucket": 0}, {"text": "Spend to win share at a loss", "bucket": 1}, {"text": "Count on raising money soon", "bucket": 1}], "explanation": "In a long downturn, runway and profitable work matter more than share."}, "numbers": {"kind": "numberSense", "prompt": "For what share of booked loads did Convoy automate the carrier side?", "min": 0, "max": 100, "value": 98, "unit": "%", "explanation": "Its tech automated the carrier side for 98% of booked loads."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You run operations. The CEO asks which customers to keep.", "prompt": "What do you recommend?", "options": ["Keep the lanes and customers that earn a margin", "Keep every customer, however little they pay", "Drop the largest customers first"], "correctIndex": 0, "consequences": ["You protect cash by focusing on profitable work.", "Unprofitable loads burn your runway.", "Size alone does not decide profit."], "explanation": "In a slump, profitable lanes keep the company alive."}, "proReasoning": "Operators sort customers by margin, not by size.", "commonMistake": "Chasing volume that loses money.", "mentalModel": "Keep the work that pays."}, "invest": {"call": {"kind": "theCall", "situation": "You are on the board. Freight has been weak for a year.", "prompt": "What do you push management to do?", "options": ["Plan an IPO right in the middle of the slump", "Stretch the runway past the expected downturn", "Spend heavily to buy market share now"], "correctIndex": 1, "consequences": ["Markets rarely reward brokers in a downturn.", "You protect the company until the cycle turns.", "Spending in a slump burns cash fast."], "explanation": "Convoy and Transfix show the downturn can outlast the cash."}, "proReasoning": "Board members insist on runway in cyclical businesses.", "commonMistake": "Betting the company on a fast recovery.", "mentalModel": "Outlast the downturn."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your software works well, but freight margins are thin.", "prompt": "What option could keep the company alive?", "options": ["Buy a fleet of trucks to cut costs", "Double sales staff to find more loads", "Sell the software to others as a service"], "correctIndex": 2, "consequences": ["Trucks add fixed costs in a slump.", "More staff raises costs before revenue.", "You add income that does not ride the freight spread."], "explanation": "Transfix kept its TMS and sold it as a service. Software income can outlast a slump."}, "proReasoning": "Founders look for income streams that do not move with the cycle.", "commonMistake": "Doubling down on the part of the business the cycle is hurting.", "mentalModel": "Find income the cycle cannot reach."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why the board is split on growing versus cutting.", "prompt": "What is the core trade-off?", "options": ["Market share now versus survival later", "Software quality versus app design", "Truck size versus top speed"], "correctIndex": 0, "consequences": ["You see the choice every cyclical startup faces.", "The question is about money, not design.", "A digital broker does not own trucks."], "explanation": "Growing may win share but can burn the cash needed to survive."}, "proReasoning": "In cyclical markets, staying alive comes first.", "commonMistake": "Assuming the biggest player always wins.", "mentalModel": "Survive first, grow later."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2f3ae35ff73e$ml$]::text[]),
($ml$640a5a90-6e2c-5852-9386-abd39eeb3a7e$ml$::uuid, $ml$logistics$ml$, 7, 1, $ml${"id": "logistics-d7-c1", "title": "Rail has a strong year", "lessonTitle": "Why trains beat trucks on distance", "slot": 1, "type": "apply", "brief": {"headline": "US railroads moved 14.06 million intermodal units in 2025, up 1.5% and the second-highest on record. Carloads rose 1.5% to about 11.5 million.", "kicker": "Apply the rule: distance, weight and speed pick the mode.", "fullText": "Logistics Management, citing the Association of American Railroads, reported that US carloads reached 11,508,767 in 2025. That was the largest annual gain since 2001.\n\nIntermodal units are containers and trailers that ride on trains for the long part of a trip and on trucks at each end. Carloads are heavy bulk goods such as grain, chemicals and coal moved in rail cars.", "sources": [{"url": "https://www.logisticsmgmt.com/article/37th_state_of_logistics_rail_intermodal", "label": "Logistics Management, 37th State of Logistics: rail and intermodal"}, {"url": "https://www.aar.org/article/freight-rail-greening-america", "label": "AAR, freight rail and the environment"}]}, "evidence": {"kind": "sortSignal", "prompt": "Better suited to rail or to truck?", "buckets": ["Rail", "Truck"], "items": [{"text": "Grain moving 1,200 miles", "bucket": 0}, {"text": "Containers crossing the country", "bucket": 0}, {"text": "Same-day store delivery", "bucket": 1}, {"text": "A short 80-mile urgent run", "bucket": 1}], "explanation": "Rail wins on long, heavy moves. Trucks win on short, fast and flexible ones."}, "numbers": {"kind": "numberSense", "prompt": "How many million intermodal units did US railroads move in 2025?", "min": 0, "max": 20, "value": 14.1, "unit": "M", "explanation": "About 14.06 million units, the second-highest on record."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a railroad. They ask what drove 2025 volume.", "prompt": "What do you say about intermodal?", "options": ["Trucks stopped carrying any long freight", "Rail took over same-day parcel delivery", "Long-haul containers moved from road to rail"], "correctIndex": 2, "consequences": ["Trucks still carry most freight.", "Same-day delivery stays on trucks.", "You link intermodal to the long-haul strength of rail."], "explanation": "Intermodal moves containers on rail for the long leg and trucks at each end."}, "proReasoning": "Strong candidates explain where rail competes with trucks: long, steady lanes.", "commonMistake": "Describing rail and trucks as rivals on every trip.", "mentalModel": "Rail wins the long leg."}, "invest": {"call": {"kind": "theCall", "situation": "Rail carloads posted their largest annual gain since 2001.", "prompt": "What does that tell an investor about railroads?", "options": ["Heavy freight demand on rail was firm in 2025", "Railroads will double volume next year", "Rail has replaced trucks in most freight"], "correctIndex": 0, "consequences": ["You read the data for what it says about 2025.", "One good year does not predict a doubling.", "Trucks still carry most US tonnage."], "explanation": "The gain was 1.5%, the largest since 2001. That signals steady demand, not a boom."}, "proReasoning": "Investors read records in context. A 1.5% gain can be a record in a slow-growth business.", "commonMistake": "Reading a record as a sign of explosive growth.", "mentalModel": "Put records in context."}, "build_startup": {"call": {"kind": "theCall", "situation": "Intermodal volume hit its second-highest level on record.", "prompt": "Where can a startup help?", "options": ["Replacing freight trains with drones", "Booking the truck legs at each rail end", "Building a brand new railroad line"], "correctIndex": 1, "consequences": ["Drones do not carry containers.", "Every intermodal box needs trucks at both ends.", "New rail lines take huge capital and years."], "explanation": "Intermodal needs drayage at each end. Coordinating those truck moves is a software problem."}, "proReasoning": "Founders find the handoffs between modes. That is where delays happen.", "commonMistake": "Trying to compete with railroads on rails.", "mentalModel": "Work the handoffs."}, "curiosity": {"call": {"kind": "theCall", "situation": "You learn intermodal means one container rides both a truck and a train.", "prompt": "Why split the trip?", "options": ["Trains are faster for short city trips", "Trucks cannot legally carry containers far", "Trains cost less on distance; trucks reach doors"], "correctIndex": 2, "consequences": ["Trucks win short city trips.", "Trucks can, but cost more over distance.", "You see each mode doing what it does best."], "explanation": "Rail is three to four times more fuel efficient. Trucks deliver to the door."}, "proReasoning": "Combine modes to get the strengths of each.", "commonMistake": "Thinking freight must stay on one mode.", "mentalModel": "Use each mode where it is strongest."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:035c1fec97de$ml$]::text[]),
($ml$7f67cdb9-86bc-5a52-9f82-80a17df24771$ml$::uuid, $ml$logistics$ml$, 7, 2, $ml${"id": "logistics-d7-c2", "title": "The train has no 11-hour clock", "lessonTitle": "Why trains beat trucks on distance", "slot": 2, "type": "connect", "brief": {"headline": "A freight train moves a ton nearly 500 miles on a gallon of fuel. A truck driver can drive at most 11 hours after 10 off.", "kicker": "Connect day 5 and day 7: hours limits and long hauls.", "fullText": "Day 5 showed that the hours rules cap how far one driver can take a load each day. Day 7 shows why rail is strong on distance: trains are three to four times more fuel efficient than trucks and carry about 40% of US long-distance freight by ton-miles.\n\nOn long lanes, a truck needs rest stops or two drivers. Intermodal puts the long leg on the train and keeps trucks for the short legs at each end.", "sources": [{"url": "https://www.aar.org/article/freight-rail-greening-america", "label": "AAR, freight rail and the environment"}, {"url": "https://www.fmcsa.dot.gov/regulations/hours-service/summary-hours-service-regulations", "label": "FMCSA, hours of service summary"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Rail carries about 40% of US long-distance ton-miles.", "Rail is three to four times more fuel efficient than trucks.", "Rail accounts for most US transport greenhouse gas."], "fakeIndex": 2, "explanation": "Freight rail accounts for about 1.8% of US transportation greenhouse gas emissions."}, "numbers": {"kind": "numberSense", "prompt": "About how many miles can a train move a ton of freight on one gallon of fuel?", "min": 0, "max": 800, "value": 500, "unit": "miles", "explanation": "Nearly 500 miles per gallon per ton."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You plan freight for a manufacturer shipping 2,000 miles each week.", "prompt": "What option do you study first?", "options": ["Intermodal: rail long leg, trucks at the ends", "A solo truck driver with no rest stops at all", "Air freight for every heavy load"], "correctIndex": 0, "consequences": ["You match the mode to a long, regular lane.", "Solo drivers must stop for rest.", "Air is costly for heavy goods."], "explanation": "On long regular lanes, rail cuts fuel use and avoids hours limits on the long leg."}, "proReasoning": "Good planners test intermodal on any long, steady lane.", "commonMistake": "Defaulting to trucks for every distance.", "mentalModel": "Long lanes are rail's home."}, "invest": {"call": {"kind": "theCall", "situation": "Rail is three to four times more fuel efficient than trucks.", "prompt": "What could shift more freight to rail?", "options": ["More shopper demand for same-day delivery", "Higher fuel prices or tighter truck hours", "Shorter average delivery distances"], "correctIndex": 1, "consequences": ["Speed needs favor trucks.", "You see what tips the cost balance toward rail.", "Short trips favor trucks."], "explanation": "Rail's edge grows when fuel costs more or trucks can run fewer hours."}, "proReasoning": "Investors watch costs that change the gap between modes.", "commonMistake": "Assuming mode shares never move.", "mentalModel": "Watch the cost gap between modes."}, "build_startup": {"call": {"kind": "theCall", "situation": "Shippers want rail's lower costs but trucks' door-to-door ease.", "prompt": "What product fills that gap?", "options": ["A faster truck that drives 20 hours", "A rail line to every warehouse", "One booking for train plus truck legs"], "correctIndex": 2, "consequences": ["Hours rules still apply.", "Rail to every door is not practical.", "You hide the handoff behind one booking."], "explanation": "Shippers want one booking. Joining rail and truck legs gives them that."}, "proReasoning": "Founders package complex handoffs into one simple purchase.", "commonMistake": "Asking shippers to manage every leg themselves.", "mentalModel": "Make two modes feel like one."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why trains carry so much long-distance freight.", "prompt": "What is the main reason?", "options": ["They move heavy loads using far less fuel", "They are faster than any truck on short trips", "Trucks are not allowed on long routes"], "correctIndex": 0, "consequences": ["You see that efficiency wins on distance.", "Trucks win short trips.", "Trucks can drive any distance with rest."], "explanation": "A ton moves nearly 500 miles on a gallon by train. Over distance that saves a lot."}, "proReasoning": "Efficiency matters more as distance grows.", "commonMistake": "Thinking speed always wins.", "mentalModel": "Distance rewards efficiency."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b5a8379c8d55$ml$]::text[]),
($ml$6122263c-778a-53f9-a582-942c2344fd65$ml$::uuid, $ml$logistics$ml$, 7, 3, $ml${"id": "logistics-d7-c3", "title": "Truck or train for steel?", "lessonTitle": "Why trains beat trucks on distance", "slot": 3, "type": "decide", "brief": {"headline": "You ship heavy steel parts 1,500 miles every week. Delivery in four or five days is fine, and your truck costs keep rising.", "kicker": "Decide: move the lane to rail?", "fullText": "Rail moves a ton nearly 500 miles per gallon and is three to four times more fuel efficient than trucks. It is strongest on long, heavy moves where speed matters less.\n\nIntermodal uses trains for the long leg and trucks at each end. It is often slower than a direct truck, and it needs good handoffs at the rail yards.", "sources": [{"url": "https://www.aar.org/article/freight-rail-greening-america", "label": "AAR, freight rail and the environment"}, {"url": "https://www.logisticsmgmt.com/article/37th_state_of_logistics_rail_intermodal", "label": "Logistics Management, 37th State of Logistics: rail and intermodal"}]}, "evidence": {"kind": "faceOff", "prompt": "Which fits a heavy, long, not urgent lane?", "left": {"name": "Rail or intermodal", "note": "Cheaper on long, heavy moves"}, "right": {"name": "Direct truck", "note": "Faster, more flexible"}, "correctIndex": 0, "explanation": "Distance, weight and relaxed timing all point to rail."}, "numbers": {"kind": "numberSense", "prompt": "About what share of US long-distance ton-miles does rail carry?", "min": 0, "max": 100, "value": 40, "unit": "%", "explanation": "About 40% of long-distance freight ton-miles."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks for a recommendation on the steel lane.", "prompt": "What do you propose?", "options": ["Keep trucks because they always win", "A rail trial on part of the volume first", "Move every load to rail tomorrow"], "correctIndex": 1, "consequences": ["Trucks do not win long, heavy lanes on cost.", "You test the switch before committing.", "An instant switch risks service problems."], "explanation": "A trial shows real transit times and costs before moving everything."}, "proReasoning": "Good planners pilot a mode shift on part of a lane first.", "commonMistake": "Switching all at once without data.", "mentalModel": "Pilot before you switch."}, "invest": {"call": {"kind": "theCall", "situation": "Many shippers like you are weighing rail for heavy, long lanes.", "prompt": "Which company benefits if they switch?", "options": ["Same-day courier firms in cities", "Air cargo airlines and forwarders", "Railroads and intermodal firms"], "correctIndex": 2, "consequences": ["Couriers serve short, fast trips.", "Air serves light, valuable goods.", "Long, heavy freight moving to rail helps rail firms."], "explanation": "Shifts from road to rail add volume to railroads and intermodal firms."}, "proReasoning": "Investors follow which mode wins each type of freight.", "commonMistake": "Missing who gains when freight shifts modes.", "mentalModel": "Follow the freight to the winner."}, "build_startup": {"call": {"kind": "theCall", "situation": "You sell to shippers like this one.", "prompt": "What tool would help them decide?", "options": ["A cost and time calculator for each mode", "A new tire for long-haul trucks", "A cargo drone built for steel parts"], "correctIndex": 0, "consequences": ["You help them compare modes with real numbers.", "Tires do not answer the mode question.", "Drones cannot carry heavy steel."], "explanation": "Shippers need clear cost and time comparisons before changing modes."}, "proReasoning": "Founders build tools for decisions buyers face every week.", "commonMistake": "Building hardware for a decision problem.", "mentalModel": "Help buyers compare."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why the shipper does not just keep using trucks.", "prompt": "What makes rail attractive here?", "options": ["Trucks cannot legally carry steel", "Long distance, heavy loads, loose timing", "Rail is always faster than any truck"], "correctIndex": 1, "consequences": ["Trucks can carry steel.", "You see all three factors point to rail.", "Rail is often slower door to door."], "explanation": "Distance, weight and relaxed timing are the conditions where rail wins."}, "proReasoning": "Pick the mode by distance, weight and speed.", "commonMistake": "Thinking one mode is best for everything.", "mentalModel": "Distance, weight, speed."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3a9b0579ad03$ml$]::text[]),
($ml$1fc44d95-7fcf-587b-b419-1eedc84837cc$ml$::uuid, $ml$logistics$ml$, 8, 1, $ml${"id": "logistics-d8-c1", "title": "Rates ease as peak fades", "lessonTitle": "When shipping a container got expensive", "slot": 1, "type": "apply", "brief": {"headline": "Drewry's World Container Index fell 2% to $4,547 per 40-foot container on 16 July 2026. Shanghai to Rotterdam fell 1% to $4,873.", "kicker": "Apply the rule: capacity moves container prices.", "fullText": "Shanghai to Los Angeles fell 3% to $6,272. Drewry said peak season demand was fading and carriers planned nine blank sailings on the transpacific the following week.\n\nTariff front-loading was easing, while tensions between the US and Iran and threats around the Bab el-Mandeb strait kept risk in the market. Blank sailings, voyages carriers cancel, are a way to cut capacity when demand softens.", "sources": [{"url": "https://www.thedcn.com.au/news/world-container-index-16-july-2026", "label": "Daily Cargo News, Drewry World Container Index, 16 July 2026"}, {"url": "https://seatrade-maritime.com/containers/container-rates-rise-again-more-come", "label": "Seatrade Maritime, container rates rise again"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why would carriers cancel nine sailings when demand fades?", "options": ["To raise capacity and lower prices", "Because ports were shut for good", "To cut capacity and support prices"], "correctIndex": 2, "explanation": "Removing sailings shrinks supply, which helps hold rates up as demand slows."}, "numbers": {"kind": "numberSense", "prompt": "What was the WCI composite rate per 40-foot container on 16 July 2026, in thousand dollars?", "min": 0, "max": 8, "value": 4.5, "unit": "K", "explanation": "The composite was $4,547 per 40-foot container."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You buy ocean freight for an importer. Rates dipped this week.", "prompt": "What do you tell your manager?", "options": ["Rates eased; blank sailings may hold them", "Rates will fall to 2019 levels next week", "Rates no longer matter for our costs"], "correctIndex": 0, "consequences": ["You report the dip and the supply response.", "One weekly dip does not mean a return to 2019.", "Ocean rates still drive import costs."], "explanation": "Demand is fading, but carriers are cutting sailings to defend prices."}, "proReasoning": "Good buyers read both demand and carrier capacity moves.", "commonMistake": "Treating one weekly drop as a trend.", "mentalModel": "Watch what carriers do with capacity."}, "invest": {"call": {"kind": "theCall", "situation": "Container rates fell 2% while carriers cancel sailings.", "prompt": "What should an investor in shipping lines watch?", "options": ["Whether ships get faster this year", "Whether blank sailings stop the slide", "Whether one week sets the yearly trend"], "correctIndex": 1, "consequences": ["Speed is not the issue here.", "You track the tool carriers use to defend margins.", "Weekly moves are noisy."], "explanation": "Carriers cut sailings to protect prices. Whether that works shapes their earnings."}, "proReasoning": "Investors watch carrier discipline on capacity in a soft market.", "commonMistake": "Reading a weekly index as the full story.", "mentalModel": "Supply discipline sets the floor."}, "build_startup": {"call": {"kind": "theCall", "situation": "Importers face rates that swing week to week.", "prompt": "What product could help them?", "options": ["A new container ship for small importers", "A tool that fixes rates forever", "Alerts on rate moves and cancelled sailings"], "correctIndex": 2, "consequences": ["Ships cost far too much for a startup.", "No tool can freeze market prices.", "You help importers react to changes fast."], "explanation": "Importers need to know when rates and capacity change."}, "proReasoning": "Founders turn noisy market data into simple alerts.", "commonMistake": "Promising to control prices you cannot control.", "mentalModel": "Turn noise into signals."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that ships were cancelled even though rates were still high.", "prompt": "Why would carriers do that?", "options": ["Fewer sailings slow the price drop", "They ran out of fuel for ships", "Ports refused all ships that week"], "correctIndex": 0, "consequences": ["You see capacity being managed to protect prices.", "Fuel was not the reported reason.", "Ports were open."], "explanation": "With demand fading, carriers removed sailings to keep supply tight."}, "proReasoning": "Prices depend on supply as much as demand.", "commonMistake": "Thinking carriers always sail every planned voyage.", "mentalModel": "Cutting supply props up price."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:838d39bfef25$ml$]::text[]),
($ml$7ba09bc9-7f34-5821-8f3b-488c71aaa560$ml$::uuid, $ml$logistics$ml$, 8, 2, $ml${"id": "logistics-d8-c2", "title": "Price is a capacity signal", "lessonTitle": "When shipping a container got expensive", "slot": 2, "type": "connect", "brief": {"headline": "In June 2024 the WCI hit $5,117 per 40-foot container, 260% above the 2019 average of $1,420. Red Sea diversions sent ships around Africa.", "kicker": "Connect day 4 and day 8: read prices as capacity signals.", "fullText": "Day 4 showed that freight spending can rise while volumes fall, because price per load changes. Day 8 shows the ocean version.\n\nWhen ships avoided the Red Sea and sailed around the Cape of Good Hope, each voyage took longer. The same fleet could make fewer trips, so effective capacity shrank and prices rose. Shanghai to Rotterdam reached $6,867 per container.", "sources": [{"url": "https://seatrade-maritime.com/containers/container-rates-rise-again-more-come", "label": "Seatrade Maritime, container rates rise again"}, {"url": "https://www.freightwaves.com/?p=562614", "label": "FreightWaves, freight shipment decline streak extends to 30 months"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the chain in order.", "steps": ["Ships avoid the Red Sea", "Voyages around Africa take longer", "Each ship makes fewer trips a year", "Container rates rise"], "explanation": "Longer voyages shrink effective capacity, which pushes prices up."}, "numbers": {"kind": "numberSense", "prompt": "What was the 2019 average WCI rate per 40-foot container, in thousand dollars?", "min": 0, "max": 4, "value": 1.4, "unit": "K", "explanation": "The 2019 average was $1,420."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your company's import costs jumped in 2024. Finance asks why.", "prompt": "What is your one-line answer?", "options": ["Our products got heavier this year", "Longer voyages cut capacity and lift rates", "Ports charged higher fees for all goods"], "correctIndex": 1, "consequences": ["Product weight did not change rates.", "You explain the capacity cause behind the price.", "Port fees were not the main driver."], "explanation": "Red Sea diversions made voyages longer, shrinking capacity and raising rates."}, "proReasoning": "Strong analysts link price moves to the capacity change behind them.", "commonMistake": "Blaming the wrong cost driver.", "mentalModel": "Find the capacity behind the price."}, "invest": {"call": {"kind": "theCall", "situation": "Rates jumped 260% above 2019 because voyages got longer.", "prompt": "What could bring rates down?", "options": ["More ships sailing around Africa", "Higher demand for imported goods", "Ships going back to the Red Sea route"], "correctIndex": 2, "consequences": ["Longer routes keep capacity tight.", "More demand pushes rates up.", "Shorter voyages free up capacity."], "explanation": "When routes shorten, the same fleet carries more, and rates ease."}, "proReasoning": "Investors track the route changes that free or tie up capacity.", "commonMistake": "Expecting rates to fall while routes stay long.", "mentalModel": "Shorter voyages, more capacity."}, "build_startup": {"call": {"kind": "theCall", "situation": "Importers were caught off guard by the Red Sea price jump.", "prompt": "What would help them next time?", "options": ["Scenario tools showing rate risk by route", "A promise that rates never rise again", "A new canal built by your startup"], "correctIndex": 0, "consequences": ["You help them plan for disruptions.", "No one can promise stable rates.", "Canals are not a startup project."], "explanation": "Route disruptions repeat. Planning tools help importers prepare."}, "proReasoning": "Founders build for problems that keep coming back.", "commonMistake": "Selling certainty in an uncertain market.", "mentalModel": "Help buyers plan for shocks."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why a longer route makes every container cost more.", "prompt": "What is the link?", "options": ["Ships burn less fuel on long routes", "The same ships carry less freight a year", "Longer routes have more ports to pay"], "correctIndex": 1, "consequences": ["Longer routes burn more fuel.", "You see that time at sea is capacity used up.", "Port count is not the main effect."], "explanation": "Each ship spends more time per trip, so the fleet carries less. Less supply means higher prices."}, "proReasoning": "Time is capacity in transport.", "commonMistake": "Thinking routes only change fuel costs.", "mentalModel": "Time at sea is capacity used."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3f8f32d64b72$ml$]::text[]),
($ml$dd057e67-fb12-5c04-86c5-1f306e448c7f$ml$::uuid, $ml$logistics$ml$, 8, 3, $ml${"id": "logistics-d8-c3", "title": "Lock in or wait it out?", "lessonTitle": "When shipping a container got expensive", "slot": 3, "type": "decide", "brief": {"headline": "You import furniture from Asia. A new disruption is lengthening voyages and spot rates are climbing fast.", "kicker": "Decide: sign a contract rate or ride the spot market?", "fullText": "In 2024, Red Sea diversions sent ships around Africa and pushed the WCI to $5,117 per container, 260% above the 2019 average. Longer voyages shrink effective capacity and raise prices.\n\nA carrier offers you a fixed contract rate for the next six months. It is below today's spot price but well above last year's.", "sources": [{"url": "https://seatrade-maritime.com/containers/container-rates-rise-again-more-come", "label": "Seatrade Maritime, container rates rise again"}, {"url": "https://www.thedcn.com.au/news/world-container-index-16-july-2026", "label": "Daily Cargo News, Drewry World Container Index, 16 July 2026"}]}, "evidence": {"kind": "sortSignal", "prompt": "Points toward locking in or toward waiting?", "buckets": ["Lock in", "Wait"], "items": [{"text": "Voyages are getting longer", "bucket": 0}, {"text": "Carriers are filling up fast", "bucket": 0}, {"text": "Ships expected to return to short routes", "bucket": 1}, {"text": "Demand is fading after peak", "bucket": 1}], "explanation": "Shrinking capacity favors locking in. Returning capacity or fading demand favors waiting."}, "numbers": {"kind": "numberSense", "prompt": "How far above the 2019 average was the WCI in June 2024?", "min": 0, "max": 400, "value": 260, "unit": "%", "explanation": "It was 260% above the 2019 average of $1,420."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CFO asks whether to sign the six-month contract.", "prompt": "What do you recommend?", "options": ["Put every box on spot and hope rates fall", "Stop importing until rates return to 2019", "Lock in part of volume, keep some on spot"], "correctIndex": 2, "consequences": ["All-spot exposes you to further spikes.", "Stopping imports empties your shelves.", "You cap risk while keeping room to benefit."], "explanation": "Splitting volume limits the damage if rates rise and keeps some benefit if they fall."}, "proReasoning": "Good buyers hedge, not bet, when capacity is shrinking.", "commonMistake": "Going all-in on one guess about rates.", "mentalModel": "Hedge, do not bet."}, "invest": {"call": {"kind": "theCall", "situation": "Many importers sign contracts during a capacity squeeze.", "prompt": "Who benefits most from that?", "options": ["Carriers locking in high rates for months", "Importers who wait for spot to fall", "Ports that charge flat fees per box"], "correctIndex": 0, "consequences": ["Carriers turn a spike into steady revenue.", "Waiting importers face uncertain prices.", "Flat fees do not rise with rates."], "explanation": "Contracts signed in a squeeze lock in high rates for carriers."}, "proReasoning": "Investors watch contract rates, not just spot, for carrier earnings.", "commonMistake": "Looking only at spot prices.", "mentalModel": "Contracts carry spikes forward."}, "build_startup": {"call": {"kind": "theCall", "situation": "Importers struggle to decide between contract and spot.", "prompt": "What could you build for them?", "options": ["A new shipping line for one importer", "A tool that splits volume by risk and price", "A guarantee that spot always beats contract"], "correctIndex": 1, "consequences": ["A shipping line needs vast capital.", "You help them manage the mix.", "No one can guarantee that."], "explanation": "The decision is about balancing risk. A tool that models the mix helps."}, "proReasoning": "Founders turn recurring trade-offs into decision tools.", "commonMistake": "Promising outcomes the market controls.", "mentalModel": "Model the mix."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why the contract rate is below spot but above last year.", "prompt": "Why would a carrier offer that?", "options": ["It expects rates to fall to zero", "It is required to by federal law", "It trades upside for steady volume"], "correctIndex": 2, "consequences": ["Carriers do not expect free shipping.", "No law sets these rates.", "You see both sides gaining something."], "explanation": "The carrier gets reliable volume, and you get price certainty."}, "proReasoning": "Contracts trade upside for certainty on both sides.", "commonMistake": "Thinking one side always loses in a contract.", "mentalModel": "Certainty has a price."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:bee479191112$ml$]::text[]),
($ml$e7b11cf5-e409-562c-a8b4-d909b516197e$ml$::uuid, $ml$logistics$ml$, 9, 1, $ml${"id": "logistics-d9-c1", "title": "A railroad across three countries", "lessonTitle": "The first coast-to-coast railroad", "slot": 1, "type": "apply", "brief": {"headline": "In March 2023, the STB approved Canadian Pacific's $31 billion purchase of Kansas City Southern. It created the first single-line railroad spanning Canada, the US and Mexico.", "kicker": "Apply the rule: regulators decide how big a network gets.", "fullText": "The Surface Transportation Board set an unprecedented seven-year oversight period for the combined railroad, CPKC. The railroads said the deal would shift about 64,000 truckloads a year from highways to rail and add 800 union jobs in the US.\n\nA single-line route avoids handing freight from one railroad to another, which can save time and cost.", "sources": [{"url": "https://www.cnbc.com/2023/03/15/us-regulator-approves-canadian-pacific-purchase-of-kansas-city-southern-.html", "label": "CNBC, US regulator approves Canadian Pacific purchase of Kansas City Southern"}, {"url": "https://www.freightwaves.com/news/how-rail-mega-merger-moved-ahead-and-stb-avoided-making-history", "label": "FreightWaves, how the rail mega-merger moved ahead"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The STB set a seven-year oversight period for CPKC.", "The deal was valued at $31 billion.", "The STB rejected the merger in March 2023."], "fakeIndex": 2, "explanation": "The STB approved the merger in March 2023, with seven years of oversight."}, "numbers": {"kind": "numberSense", "prompt": "How many thousand truckloads a year was CPKC expected to shift to rail?", "min": 0, "max": 150, "value": 64, "unit": "K", "explanation": "About 64,000 truckloads a year."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at CPKC. They ask what makes their network different.", "prompt": "What is the best answer?", "options": ["It only serves the US East Coast", "One railroad from Canada to Mexico", "It has the most trucks in North America"], "correctIndex": 1, "consequences": ["Its network spans three countries.", "You name the single-line reach that defines it.", "CPKC is a railroad, not a trucking fleet."], "explanation": "CPKC is the first single-line railroad across Canada, the US and Mexico."}, "proReasoning": "Candidates who name the network edge show they know the business.", "commonMistake": "Describing a railroad by its size alone.", "mentalModel": "Name the network edge."}, "invest": {"call": {"kind": "theCall", "situation": "The STB approved CPKC with seven years of oversight.", "prompt": "What does that oversight mean for investors?", "options": ["The merger can be undone at any time", "Prices are now fixed by the government", "Regulators will watch its conduct"], "correctIndex": 2, "consequences": ["Oversight is monitoring, not reversal.", "Oversight does not set all prices.", "You see the deal came with ongoing scrutiny."], "explanation": "Seven years of oversight lets the STB monitor how the merged railroad behaves."}, "proReasoning": "Investors factor regulatory conditions into merger returns.", "commonMistake": "Treating approval as the end of regulation.", "mentalModel": "Approval comes with conditions."}, "build_startup": {"call": {"kind": "theCall", "situation": "CPKC opens single-line rail service between Mexico and Canada.", "prompt": "What opportunity does that create?", "options": ["Services for new cross-border lanes", "A rival railroad across three countries", "Cargo planes for steel and grain"], "correctIndex": 0, "consequences": ["New lanes need customs, drayage and booking help.", "Building a rival takes decades.", "Air does not suit heavy bulk goods."], "explanation": "New cross-border rail lanes need supporting services like customs and trucking."}, "proReasoning": "Founders build around new infrastructure rather than competing with it.", "commonMistake": "Competing head-on with a network giant.", "mentalModel": "Build around new networks."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why a single-line railroad matters.", "prompt": "What is the benefit?", "options": ["Shippers stop needing any trucks", "Freight avoids handoffs between lines", "Trains travel at twice the speed"], "correctIndex": 1, "consequences": ["Trucks still serve the ends.", "You see how fewer handoffs save time.", "Speed is not the main gain."], "explanation": "Handing freight between railroads adds delay. One line removes that step."}, "proReasoning": "Fewer handoffs mean fewer delays.", "commonMistake": "Thinking a bigger network is only about size.", "mentalModel": "Fewer handoffs, fewer delays."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e3e9a298d82b$ml$]::text[]),
($ml$e95ae309-fe59-5b81-af66-1705b6ee3174$ml$::uuid, $ml$logistics$ml$, 9, 2, $ml${"id": "logistics-d9-c2", "title": "Coast to coast on one railroad", "lessonTitle": "The first coast-to-coast railroad", "slot": 2, "type": "connect", "brief": {"headline": "Union Pacific and Norfolk Southern announced an $85 billion merger in July 2025. In May 2026 the STB conditionally accepted their revised application.", "kicker": "Connect day 7 and day 9: rail wins distance, mergers add reach.", "fullText": "Day 7 showed that rail is strongest on long hauls, carrying about 40% of US long-distance ton-miles. Day 9 shows why a coast-to-coast railroad is attractive: one network could carry freight across the country without a handoff in the middle.\n\nThe Surface Transportation Board must approve major rail mergers. Accepting the application starts the review; it is not approval.", "sources": [{"url": "https://www.freightwaves.com/news/how-rail-mega-merger-moved-ahead-and-stb-avoided-making-history", "label": "FreightWaves, how the rail mega-merger moved ahead"}, {"url": "https://www.aar.org/article/freight-rail-greening-america", "label": "AAR, freight rail and the environment"}]}, "evidence": {"kind": "faceOff", "prompt": "What did the STB do in May 2026?", "left": {"name": "Accepted the application", "note": "Review can begin, with conditions"}, "right": {"name": "Approved the merger", "note": "Deal cleared to close"}, "correctIndex": 0, "explanation": "Conditionally accepting the revised application starts the review. It is not final approval."}, "numbers": {"kind": "numberSense", "prompt": "What is the value of the Union Pacific and Norfolk Southern deal, in billion dollars?", "min": 0, "max": 150, "value": 85, "unit": "B", "explanation": "About $85 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A friend says the UP and NS merger is done.", "prompt": "How do you correct them?", "options": ["Yes, it closed back in July 2025", "The STB rejected it outright in May 2026", "The STB accepted the filing; review goes on"], "correctIndex": 2, "consequences": ["July 2025 was the announcement.", "The STB accepted the revised filing.", "You separate acceptance from approval."], "explanation": "Acceptance starts the review. Approval would come later, if at all."}, "proReasoning": "People in regulated industries track each formal step precisely.", "commonMistake": "Treating an announcement as a closed deal.", "mentalModel": "Announced is not approved."}, "invest": {"call": {"kind": "theCall", "situation": "The UP and NS merger is under STB review.", "prompt": "What is the biggest risk to the deal case?", "options": ["Conditions or rejection from the STB", "Trains getting slower after the merger", "Rail losing all long-haul freight"], "correctIndex": 0, "consequences": ["You see regulation decides the outcome.", "Speed is not the main risk.", "Rail still carries much long-haul freight."], "explanation": "The STB decides whether and on what terms the deal closes."}, "proReasoning": "Investors in big mergers price the regulator's decision first.", "commonMistake": "Assuming a large deal will clear because it was announced.", "mentalModel": "The regulator holds the key."}, "build_startup": {"call": {"kind": "theCall", "situation": "A coast-to-coast railroad could make transcontinental rail lanes simpler.", "prompt": "How might a startup prepare?", "options": ["Ignore it, since mergers never matter", "Plan for new lanes; wait for approval", "Spend now as if the merger has closed"], "correctIndex": 1, "consequences": ["Rail mergers reshape lanes.", "You prepare without betting on an uncertain outcome.", "The deal may change or fail."], "explanation": "The merger may create new lanes, but approval is not certain."}, "proReasoning": "Founders prepare for regulatory change without betting the company on it.", "commonMistake": "Building for a deal that has not been approved.", "mentalModel": "Prepare, do not bet."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why the US has no coast-to-coast railroad already.", "prompt": "What is part of the reason?", "options": ["Trains cannot cross the Rockies", "Railroads are banned from merging at all", "Big rail mergers need regulator approval"], "correctIndex": 2, "consequences": ["Railroads already cross mountains.", "Mergers are allowed with approval.", "You see the STB's role in network size."], "explanation": "The STB decides how much any one railroad network can control."}, "proReasoning": "Regulators shape how big networks can grow.", "commonMistake": "Thinking networks grow only by business choice.", "mentalModel": "Regulators shape networks."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:82b6ab37d404$ml$]::text[]),
($ml$02b12853-b971-5084-a12a-a5dff96a6916$ml$::uuid, $ml$logistics$ml$, 9, 3, $ml${"id": "logistics-d9-c3", "title": "Your railroad wants to merge", "lessonTitle": "The first coast-to-coast railroad", "slot": 3, "type": "decide", "brief": {"headline": "You ship chemicals by rail from a plant served by only one railroad. That railroad plans a big merger that needs STB approval.", "kicker": "Decide: what do you ask the regulator for?", "fullText": "The STB approves major rail mergers and can attach conditions. It approved CPKC with seven years of oversight, and in May 2026 it conditionally accepted the revised Union Pacific and Norfolk Southern application.\n\nA merger can add single-line reach and cut handoffs. For a shipper with only one railroad, it can also mean fewer options if service or prices worsen.", "sources": [{"url": "https://www.freightwaves.com/news/how-rail-mega-merger-moved-ahead-and-stb-avoided-making-history", "label": "FreightWaves, how the rail mega-merger moved ahead"}, {"url": "https://www.cnbc.com/2023/03/15/us-regulator-approves-canadian-pacific-purchase-of-kansas-city-southern-.html", "label": "CNBC, US regulator approves Canadian Pacific purchase of Kansas City Southern"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What is your strongest request to the STB?", "options": ["Conditions that protect service and access", "Blocking every rail merger in the US", "Letting railroads set any price they want"], "correctIndex": 0, "explanation": "Conditions on service and access can protect shippers while the merger goes ahead."}, "numbers": {"kind": "numberSense", "prompt": "How many years of oversight did the STB set for CPKC?", "min": 0, "max": 15, "value": 7, "unit": "years", "explanation": "An unprecedented seven-year oversight period."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You manage logistics at the chemical plant.", "prompt": "What do you prepare first?", "options": ["Data on your service and costs today", "A plan to stop shipping by rail", "A press release attacking the merger"], "correctIndex": 0, "consequences": ["You give the regulator facts to act on.", "Rail may still be your cheapest option.", "Facts persuade regulators more than noise."], "explanation": "Regulators act on evidence. Your current service data shows what is at stake."}, "proReasoning": "Good logistics managers build a fact base before any regulatory filing.", "commonMistake": "Arguing without data.", "mentalModel": "Bring data to the regulator."}, "invest": {"call": {"kind": "theCall", "situation": "Shippers file requests for conditions on a big rail merger.", "prompt": "What should an investor watch?", "options": ["Whether trains get new paint", "Which conditions the STB attaches", "How many shippers complain online"], "correctIndex": 1, "consequences": ["Paint does not change returns.", "Conditions shape the merged railroad's returns.", "Complaints matter only if they shape conditions."], "explanation": "Conditions can limit pricing or require access, changing the deal's value."}, "proReasoning": "Investors price merger conditions into their estimates.", "commonMistake": "Ignoring conditions until after the decision.", "mentalModel": "Conditions change the value."}, "build_startup": {"call": {"kind": "theCall", "situation": "Many shippers face the same question during rail mergers.", "prompt": "What could you offer them?", "options": ["A new railroad built just for chemicals", "Lobbying to ban all freight trains", "Tools that track rail service and costs"], "correctIndex": 2, "consequences": ["New railroads take decades.", "Rail moves essential freight.", "You give shippers the data they need in reviews."], "explanation": "Shippers need service data to make their case. Tracking tools supply it."}, "proReasoning": "Founders serve buyers facing recurring regulatory moments.", "commonMistake": "Solving with infrastructure what data could solve.", "mentalModel": "Give shippers the data."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why one shipper's request could matter to a regulator.", "prompt": "Why does it?", "options": ["The STB weighs harm to captive shippers", "Regulators only listen to railroads", "Shippers decide mergers by vote"], "correctIndex": 0, "consequences": ["You see how captive shippers shape conditions.", "The STB hears from shippers too.", "The STB decides, not a vote."], "explanation": "Shippers served by one railroad can be hurt most by mergers. The STB weighs that."}, "proReasoning": "Those with the fewest options often shape the conditions.", "commonMistake": "Thinking regulators ignore customers.", "mentalModel": "Few options, bigger voice."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1ca82f997124$ml$]::text[]),
($ml$2fe7df3b-7720-5779-982b-c1bb29d29d29$ml$::uuid, $ml$logistics$ml$, 10, 1, $ml${"id": "logistics-d10-c1", "title": "Air cargo grows, one lane shrinks", "lessonTitle": "Light cargo, heavy value", "slot": 1, "type": "apply", "brief": {"headline": "Global air cargo demand rose 3.4% in 2025, IATA reported. Demand between Asia and North America fell 0.8%, which IATA tied to tariffs and the end of the US de minimis exemption.", "kicker": "Apply the rule: value and urgency decide who flies.", "fullText": "International demand grew 4.2% and capacity rose 3.7%, leaving a load factor of 45.7%. December 2025 demand was up 4.3% from a year earlier.\n\nThe Asia to North America lane held a 23.4% share of the market, down 1.2 points. The de minimis exemption had let low-value parcels enter the US duty free, and many of them came by air from Asia.", "sources": [{"url": "https://www.iata.org/en/pressroom/2026-releases/2026-01-29-01/", "label": "IATA, global air cargo demand hit a record in 2025"}, {"url": "https://www.iata.org/en/publications/newsletters/tracker/cargo-tracker-january-2025/voac/", "label": "IATA, the value of air cargo"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the chain in order.", "steps": ["The US ends the de minimis exemption", "Low-value parcels from Asia now face duties", "Fewer small parcels are flown to the US", "Asia to North America air demand falls 0.8%"], "explanation": "Removing duty-free entry cut the flow of cheap parcels that filled planes on that lane."}, "numbers": {"kind": "numberSense", "prompt": "What was the global air cargo load factor in 2025?", "min": 0, "max": 100, "value": 45.7, "unit": "%", "explanation": "The load factor was 45.7%, with demand up 3.4% and capacity up 3.7%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join an air cargo airline as an analyst. Your boss asks about the US lane.", "prompt": "What is your read?", "options": ["Planes got too slow for the route", "Air cargo is shrinking everywhere now", "Policy cut parcel flows on that lane"], "correctIndex": 2, "consequences": ["Speed did not change.", "Global demand rose 3.4%.", "You link the drop to tariffs and de minimis."], "explanation": "Global demand grew, but tariffs and the end of de minimis cut Asia to North America demand."}, "proReasoning": "Strong analysts separate a lane problem from a market problem.", "commonMistake": "Reading one lane as the whole market.", "mentalModel": "Split the lane from the market."}, "invest": {"call": {"kind": "theCall", "situation": "Global air demand rose 3.4% but capacity rose 3.7%.", "prompt": "What does that mean for airline cargo pricing?", "options": ["More space than demand can soften rates", "Rates must rise because demand grew", "Capacity has no effect on price"], "correctIndex": 0, "consequences": ["You see supply grew faster than demand.", "Supply growth outpaced demand growth.", "Supply always matters to price."], "explanation": "When capacity grows faster than demand, there is more space to sell and rates can soften."}, "proReasoning": "Investors compare demand growth with capacity growth.", "commonMistake": "Looking only at demand growth.", "mentalModel": "Compare demand with capacity."}, "build_startup": {"call": {"kind": "theCall", "situation": "Cheap parcels from Asia lost duty-free entry to the US.", "prompt": "What problem do sellers face now?", "options": ["Paying lower prices for air cargo", "Working out duties on each shipment", "Finding planes that fly faster"], "correctIndex": 1, "consequences": ["Their costs went up, not down.", "You target the new cost and paperwork.", "Speed is not their new problem."], "explanation": "Sellers now pay duties on small parcels. Tools that calculate and file them help."}, "proReasoning": "Founders follow policy changes to new paperwork pain.", "commonMistake": "Missing the new cost that a rule change creates.", "mentalModel": "New rules create new paperwork."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why fewer cheap parcels would hit air cargo.", "prompt": "What is the link?", "options": ["Parcels never travel by air at all", "Planes refused to carry small parcels", "Many of those parcels came by plane"], "correctIndex": 2, "consequences": ["Many e-commerce parcels fly.", "Airlines carried them gladly.", "You see that small parcels filled cargo space."], "explanation": "Low-value parcels from Asia often flew to the US. Ending de minimis cut that flow."}, "proReasoning": "Trace a policy change to the freight it moves.", "commonMistake": "Thinking trade rules only affect ships.", "mentalModel": "Rules move freight."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:edfc9e5c55b0$ml$]::text[]),
($ml$4b0ba32e-82b3-5c5d-9a75-a71685fe14a9$ml$::uuid, $ml$logistics$ml$, 10, 2, $ml${"id": "logistics-d10-c2", "title": "When delay costs more than flying", "lessonTitle": "Light cargo, heavy value", "slot": 2, "type": "connect", "brief": {"headline": "Air cargo carries about a third of world trade by value, more than $8 trillion a year. In 2024, ocean rates rose 260% above 2019 as ships sailed around Africa.", "kicker": "Connect day 8 and day 10: slow seas push goods to the air.", "fullText": "Day 8 showed that longer voyages shrink ocean capacity and raise container prices. Day 10 shows the other side: air is costly per kilo, but it carries goods whose value and urgency justify the price.\n\nWhen ships take longer, goods spend more time in transit. For high-value or time-sensitive goods, the cost of waiting can make flying worth it.", "sources": [{"url": "https://www.iata.org/en/publications/newsletters/tracker/cargo-tracker-january-2025/voac/", "label": "IATA, the value of air cargo"}, {"url": "https://seatrade-maritime.com/containers/container-rates-rise-again-more-come", "label": "Seatrade Maritime, container rates rise again"}]}, "evidence": {"kind": "sortSignal", "prompt": "Better by air or by sea?", "buckets": ["Air", "Sea"], "items": [{"text": "New phones for a launch day", "bucket": 0}, {"text": "Urgent medicines", "bucket": 0}, {"text": "Bags of cement", "bucket": 1}, {"text": "Garden furniture for spring", "bucket": 1}], "explanation": "High value and urgency favor air. Heavy, cheap or planned goods favor sea."}, "numbers": {"kind": "numberSense", "prompt": "About what share of world trade by value moves by air?", "min": 0, "max": 100, "value": 33, "unit": "%", "explanation": "About 33%, more than $8 trillion a year."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You plan shipping for a fashion brand. A ship is delayed two weeks before a launch.", "prompt": "What do you consider?", "options": ["Flying part of the stock for the launch", "Flying every item, whatever the cost", "Cancelling the launch outright"], "correctIndex": 0, "consequences": ["You protect the launch without flying everything.", "Flying everything can wipe out the margin.", "Cancelling loses sales."], "explanation": "Flying only what the launch needs balances cost against lost sales."}, "proReasoning": "Good planners compare the cost of flying with the cost of being late.", "commonMistake": "Treating air as all or nothing.", "mentalModel": "Fly what being late would cost most."}, "invest": {"call": {"kind": "theCall", "situation": "Ocean disruptions make sea freight slower and pricier.", "prompt": "Who could gain?", "options": ["Railroads moving coal and grain", "Air carriers serving urgent goods", "Bulk carriers moving cement"], "correctIndex": 1, "consequences": ["Coal does not move by air.", "Some urgent freight shifts from sea to air.", "Bulk cargo rarely flies."], "explanation": "Slow seas push some high-value, urgent goods to air."}, "proReasoning": "Investors look for substitutes that gain when one mode struggles.", "commonMistake": "Missing the knock-on effects between modes.", "mentalModel": "One mode's trouble is another's gain."}, "build_startup": {"call": {"kind": "theCall", "situation": "Shippers struggle to decide when air is worth the cost.", "prompt": "What could you build?", "options": ["A cargo airline for heavy cement", "A boat that is faster than planes", "A tool weighing delay cost against air"], "correctIndex": 2, "consequences": ["Cement is too heavy and cheap to fly.", "Ships cannot match planes on speed.", "You help them make the trade-off with numbers."], "explanation": "The decision depends on value, urgency and price. A comparison tool makes it clear."}, "proReasoning": "Founders build for decisions with real money on both sides.", "commonMistake": "Building capacity when the gap is a decision tool.", "mentalModel": "Help buyers price the delay."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder how air carries a third of trade value but little of its weight.", "prompt": "What explains it?", "options": ["Air carries light goods worth a lot", "Planes carry the heaviest goods", "Most trade weight moves by air"], "correctIndex": 0, "consequences": ["You see value and weight are different measures.", "Heavy goods go by sea or rail.", "Most weight moves by sea."], "explanation": "Air carries goods like electronics and medicines: light but valuable."}, "proReasoning": "Measure freight by value and by weight to see each mode's role.", "commonMistake": "Judging a mode only by tonnage.", "mentalModel": "Value and weight tell different stories."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1f50335be3d1$ml$]::text[]),
($ml$887111cc-c8cb-549b-8144-8d7069e132d0$ml$::uuid, $ml$logistics$ml$, 10, 3, $ml${"id": "logistics-d10-c3", "title": "Fly the launch stock?", "lessonTitle": "Light cargo, heavy value", "slot": 3, "type": "decide", "brief": {"headline": "You sell premium headphones made in Asia. A new model launches in six weeks, and sea freight takes about five weeks door to door.", "kicker": "Decide: air, sea, or a mix?", "fullText": "Air carries about a third of world trade by value, more than $8 trillion a year, because value and urgency can justify its cost. In 2025, air cargo demand between Asia and North America fell 0.8% while global demand rose 3.4%.\n\nSea freight would arrive with about a week to spare if nothing goes wrong. Air would cost much more per unit but arrive within days.", "sources": [{"url": "https://www.iata.org/en/publications/newsletters/tracker/cargo-tracker-january-2025/voac/", "label": "IATA, the value of air cargo"}, {"url": "https://www.iata.org/en/pressroom/2026-releases/2026-01-29-01/", "label": "IATA, global air cargo demand hit a record in 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Which goods fit air best?", "left": {"name": "Launch stock", "note": "High value, fixed date"}, "right": {"name": "Spare packaging", "note": "Low value, no deadline"}, "correctIndex": 0, "explanation": "High-value goods tied to a fixed date are where air pays off."}, "numbers": {"kind": "numberSense", "prompt": "About how many trillion dollars of goods move by air each year?", "min": 0, "max": 15, "value": 8, "unit": "trillion", "explanation": "More than $8 trillion a year, about a third of world trade by value."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks for a shipping plan for the launch.", "prompt": "What do you propose?", "options": ["Fly the full year of stock now", "Fly launch-week stock, ship the rest", "Ship it all by sea and hope"], "correctIndex": 1, "consequences": ["Flying everything costs far too much.", "You protect launch day and keep costs down.", "One delay could miss the launch."], "explanation": "Splitting modes covers the launch while sea handles later demand."}, "proReasoning": "Good planners match mode to the deadline each batch faces.", "commonMistake": "Picking one mode for all stock.", "mentalModel": "Match the mode to the deadline."}, "invest": {"call": {"kind": "theCall", "situation": "The brand plans to fly more stock each year for launches.", "prompt": "What should an investor check?", "options": ["Whether planes are getting larger", "How many colors the headphones come in", "Whether margins cover the air cost"], "correctIndex": 2, "consequences": ["Plane size does not decide margins.", "Colors do not change freight cost.", "You test if the strategy pays."], "explanation": "Air protects launches but costs more. Margins must absorb it."}, "proReasoning": "Investors check that faster logistics earns its cost.", "commonMistake": "Praising speed without checking cost.", "mentalModel": "Speed must pay for itself."}, "build_startup": {"call": {"kind": "theCall", "situation": "Brands like this one split shipments between air and sea.", "prompt": "What tool would help them?", "options": ["A planner that splits stock by deadline", "A private cargo jet for one brand", "A slower, cheaper cargo plane design"], "correctIndex": 0, "consequences": ["You automate the split they do by hand.", "A jet is far too costly.", "Slow planes lose air's main edge."], "explanation": "Brands need to decide which units fly and which sail. A planning tool helps."}, "proReasoning": "Founders turn manual trade-offs into software.", "commonMistake": "Building assets for a planning problem.", "mentalModel": "Automate the split."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why a brand would pay far more to fly headphones.", "prompt": "Why does it make sense?", "options": ["Ships cannot carry headphones safely", "Missing launch costs more than flying", "Planes are cheaper per unit than ships"], "correctIndex": 1, "consequences": ["Ships carry electronics all the time.", "You see the cost of being late.", "Planes cost more per unit."], "explanation": "High-value goods with a fixed date can justify the higher cost of air."}, "proReasoning": "Compare the cost of speed with the cost of delay.", "commonMistake": "Thinking the cheapest mode is always best.", "mentalModel": "Delay has a cost too."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:cf758fb96222$ml$]::text[]),
($ml$146e131e-ef60-537a-8989-12f9dde631f8$ml$::uuid, $ml$logistics$ml$, 11, 1, $ml${"id": "logistics-d11-c1", "title": "A global carbon price, delayed", "lessonTitle": "Fees on Chinese ships, paused", "slot": 1, "type": "apply", "brief": {"headline": "In October 2025, IMO member states voted 57 to 49 to adjourn the Net-Zero Framework for a year. It would have been the first global carbon pricing for any industry.", "kicker": "Apply the rule: policy can add or remove costs fast.", "fullText": "The framework would have priced greenhouse gas emissions from international shipping. The US, Russia, the UAE, Liberia and Saudi Arabia opposed it, and the US threatened tariffs and port taxes on countries that supported it.\n\nUS Secretary of State Marco Rubio called the delay another huge win. For shipping lines, the vote pushed a major new cost back by at least a year.", "sources": [{"url": "https://maritime-executive.com/article/imo-fails-to-adopt-and-adjourns-for-one-year-the-net-zero-framework", "label": "Maritime Executive, IMO adjourns the Net-Zero Framework for a year"}, {"url": "https://gcaptain.com/white-house-confirms-one-year-suspension-of-ustr-port-fees-in-u-s-china-trade-deal", "label": "gCaptain, one-year suspension of USTR port fees"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The vote to adjourn passed 57 to 49.", "The framework would price shipping emissions.", "The framework took effect worldwide in 2025."], "fakeIndex": 2, "explanation": "The framework was adjourned for a year, so it did not take effect."}, "numbers": {"kind": "numberSense", "prompt": "How many member states voted to adjourn the Net-Zero Framework?", "min": 0, "max": 150, "value": 57, "unit": "", "explanation": "The vote was 57 to 49."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work in sustainability at a shipping line.", "prompt": "How do you plan after the vote?", "options": ["Keep preparing; the delay is one year", "Drop all emissions work for good", "Assume carbon prices will never come"], "correctIndex": 0, "consequences": ["You stay ready for a rule that may return.", "The framework was paused, not killed.", "A one-year delay is not a cancellation."], "explanation": "The framework was adjourned for a year. It could come back."}, "proReasoning": "Good planners treat a delay as a delay, not an end.", "commonMistake": "Reading a pause as a final decision.", "mentalModel": "A pause is not an end."}, "invest": {"call": {"kind": "theCall", "situation": "The IMO delayed a global carbon price on shipping.", "prompt": "How might this affect shipping lines?", "options": ["It has no effect on their costs", "Lower costs now, but rules may return", "Their costs are now fixed forever"], "correctIndex": 1, "consequences": ["A carbon price would raise costs.", "You see the short-term relief and the open risk.", "Rules can change again."], "explanation": "The delay removes a cost for now. The vote could go another way later."}, "proReasoning": "Investors price policy risk as a range, not a single outcome.", "commonMistake": "Treating a political delay as settled.", "mentalModel": "Policy risk stays open."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build emissions-tracking software for ship operators.", "prompt": "What does the delay mean for you?", "options": ["The market is gone for good", "Raise prices since demand will soar", "Sales may slow, so find other buyers too"], "correctIndex": 2, "consequences": ["Rules may still return.", "Demand likely fell with the delay.", "You adapt to slower regulatory demand."], "explanation": "Regulation drove demand for emissions tools. A delay slows that demand."}, "proReasoning": "Founders avoid depending on a single rule for their market.", "commonMistake": "Building a company that only one rule can save.", "mentalModel": "Do not bet on one rule."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why one vote could matter so much to shipping costs.", "prompt": "Why does it?", "options": ["It decides if emissions get a price", "It sets the price of every new ship", "It decides which ports can open"], "correctIndex": 0, "consequences": ["You see policy as a direct cost lever.", "Ship prices are set by markets.", "Ports are not set by this vote."], "explanation": "A global carbon price would add a new cost to every voyage. The vote delayed it."}, "proReasoning": "Policy can change costs overnight.", "commonMistake": "Thinking only markets set costs.", "mentalModel": "Policy is a cost."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:697ff5243064$ml$]::text[]),
($ml$d77eae6c-fd49-50e8-b1bd-019ad2227f9a$ml$::uuid, $ml$logistics$ml$, 11, 2, $ml${"id": "logistics-d11-c2", "title": "Fees that come and go", "lessonTitle": "Fees on Chinese ships, paused", "slot": 2, "type": "connect", "brief": {"headline": "US port fees on China-linked ships began on October 14, 2025. They were suspended for one year from November 10, 2025.", "kicker": "Connect day 8 and day 11: policy moves the cost of a voyage.", "fullText": "Day 8 showed how longer voyages raised container rates by cutting capacity. Day 11 shows a different driver: trade policy. The fees came from a Section 301 action by the US Trade Representative.\n\nAfter a US-China trade deal, the fees were paused for a year. In 2026, USTR proposed extending the suspension through January 9, 2027. Costs that markets set over months, policy can add or remove in weeks.", "sources": [{"url": "https://gcaptain.com/white-house-confirms-one-year-suspension-of-ustr-port-fees-in-u-s-china-trade-deal", "label": "gCaptain, one-year suspension of USTR port fees"}, {"url": "https://www.hklaw.com/en/insights/publications/2026/10/ustr-proposes-2-month-extension-of-suspension-of-section-301", "label": "Holland & Knight, USTR proposes extending the port fee suspension"}, {"url": "https://seatrade-maritime.com/containers/container-rates-rise-again-more-come", "label": "Seatrade Maritime, container rates rise again"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the events in order.", "steps": ["USTR fees on China-linked ships begin", "A US-China trade deal is reached", "The fees are suspended for one year", "USTR proposes extending the suspension"], "explanation": "The fees started in October 2025, were paused from November 2025, and an extension was proposed in 2026."}, "numbers": {"kind": "numberSense", "prompt": "For how many months were the port fees first suspended?", "min": 0, "max": 36, "value": 12, "unit": "months", "explanation": "They were suspended for one year from November 10, 2025."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You price ocean contracts for a forwarder.", "prompt": "How do you handle the paused fees?", "options": ["Charge the fees anyway as profit", "Add clauses for fees that may return", "Assume the fees are gone for good"], "correctIndex": 1, "consequences": ["Charging fees not owed is wrong.", "You protect both sides if policy changes.", "The pause could end."], "explanation": "The fees were paused, not repealed. Contracts should cover their return."}, "proReasoning": "Good pricers write policy risk into contracts.", "commonMistake": "Pricing as if today's policy will last.", "mentalModel": "Write policy risk into the deal."}, "invest": {"call": {"kind": "theCall", "situation": "Port fees were suspended and an extension proposed.", "prompt": "What should an investor in shipping lines track?", "options": ["Whether ships change hull color", "Whether port cranes get any faster", "Whether the pause is extended or ends"], "correctIndex": 2, "consequences": ["Color does not affect fees.", "Crane speed does not set fees.", "You track the policy that drives the cost."], "explanation": "The fees could return when the pause ends. That changes costs for China-linked fleets."}, "proReasoning": "Investors track policy deadlines as cost events.", "commonMistake": "Forgetting a paused cost can come back.", "mentalModel": "Mark the policy deadlines."}, "build_startup": {"call": {"kind": "theCall", "situation": "Trade policy keeps adding and pausing costs on shipping.", "prompt": "What product could help shippers?", "options": ["Alerts on fee and tariff changes", "A ship that avoids all fees by law", "A promise that fees never return"], "correctIndex": 0, "consequences": ["You help shippers react to policy fast.", "No ship is exempt by design.", "No one can promise policy outcomes."], "explanation": "Policy changes fast. Shippers need to know what applies to each move."}, "proReasoning": "Founders track fast-changing rules for busy buyers.", "commonMistake": "Promising certainty about politics.", "mentalModel": "Track the rules for them."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why a fee could start and stop within a month.", "prompt": "What made that possible?", "options": ["Ships stopped sailing to the US", "A trade deal changed the policy", "Ports ran out of space"], "correctIndex": 1, "consequences": ["Ships kept sailing.", "You see policy shifting with negotiations.", "Space was not the reason."], "explanation": "A US-China trade deal led to the one-year suspension."}, "proReasoning": "Policy costs can move with diplomacy.", "commonMistake": "Thinking fees only change slowly.", "mentalModel": "Diplomacy moves costs."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d130eecfeaef$ml$]::text[]),
($ml$51884147-608b-5b3a-86fe-b047cf28e040$ml$::uuid, $ml$logistics$ml$, 11, 3, $ml${"id": "logistics-d11-c3", "title": "Planning for a paused fee", "lessonTitle": "Fees on Chinese ships, paused", "slot": 3, "type": "decide", "brief": {"headline": "You run a shipping line with several China-built ships calling at US ports. The fee on those ships is paused, but the pause could end.", "kicker": "Decide: how do you prepare for a fee that may return?", "fullText": "US port fees on China-linked vessels began October 14, 2025, and were suspended for one year from November 10, 2025. In 2026 USTR proposed extending the suspension through January 9, 2027.\n\nYou can keep your current fleet on US routes, move China-built ships to other trades, or plan both depending on what happens.", "sources": [{"url": "https://gcaptain.com/white-house-confirms-one-year-suspension-of-ustr-port-fees-in-u-s-china-trade-deal", "label": "gCaptain, one-year suspension of USTR port fees"}, {"url": "https://www.hklaw.com/en/insights/publications/2026/10/ustr-proposes-2-month-extension-of-suspension-of-section-301", "label": "Holland & Knight, USTR proposes extending the port fee suspension"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What is the most prudent plan?", "options": ["Assume the pause lasts forever", "A plan to swap ships if fees return", "Pull all China-built ships from trade"], "correctIndex": 1, "explanation": "A ready plan lets you act fast if the fees return, without costly moves now."}, "numbers": {"kind": "numberSense", "prompt": "On what day of October 2025 did the port fees begin?", "min": 1, "max": 31, "value": 14, "unit": "", "explanation": "They began October 14, 2025."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You manage fleet deployment at the line.", "prompt": "What do you prepare?", "options": ["A plan to scrap China-built ships", "Nothing until the pause ends", "Which ships could move routes fast"], "correctIndex": 2, "consequences": ["Scrapping ships is drastic and costly.", "Waiting leaves no time to adjust.", "You can react quickly if the fee returns."], "explanation": "A ready plan lets you swap ships if the fees return."}, "proReasoning": "Planners prepare options before deadlines, not after.", "commonMistake": "Waiting for the deadline to plan.", "mentalModel": "Prepare options early."}, "invest": {"call": {"kind": "theCall", "situation": "A shipping line with many China-built ships calls at US ports.", "prompt": "What risk do you price?", "options": ["Fees returning when the pause ends", "Ships becoming faster at sea", "US ports closing for good"], "correctIndex": 0, "consequences": ["You price the known policy risk.", "Speed is not the risk here.", "Ports are open."], "explanation": "The suspension has an end date. Fees could return."}, "proReasoning": "Investors price paused costs as possible future costs.", "commonMistake": "Ignoring a cost because it is paused.", "mentalModel": "Paused costs can return."}, "build_startup": {"call": {"kind": "theCall", "situation": "Shipping lines need to model fees by ship and route.", "prompt": "What tool could you build?", "options": ["A tool to hide where ships were built", "A fleet planner that adds policy costs", "A ship built outside every country"], "correctIndex": 1, "consequences": ["Hiding a ship's origin is not a legitimate product.", "You help lines plan around policy.", "Every ship is built somewhere."], "explanation": "Lines need fee costs in their fleet plans. A planner that includes them helps."}, "proReasoning": "Founders build tools that fold policy into everyday decisions.", "commonMistake": "Building products that dodge rules instead of planning for them.", "mentalModel": "Fold policy into the plan."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why where a ship was built matters at a US port.", "prompt": "Why does it?", "options": ["Ports only accept new ships", "Ship size depends on where it was built", "The fees targeted China-linked vessels"], "correctIndex": 2, "consequences": ["Ports accept ships of all ages.", "Size is not tied to origin.", "You see the policy link."], "explanation": "The Section 301 fees targeted China-linked vessels."}, "proReasoning": "Policy can attach costs to where a thing comes from.", "commonMistake": "Thinking only cargo is taxed.", "mentalModel": "Origin can carry a cost."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0368a30a3a8e$ml$]::text[]),
($ml$a774117d-3120-56c6-a7fc-47f5d5f0df46$ml$::uuid, $ml$logistics$ml$, 12, 1, $ml${"id": "logistics-d12-c1", "title": "Driverless trucks go public", "lessonTitle": "Trucks with no one inside", "slot": 1, "type": "apply", "brief": {"headline": "Kodiak went public on Nasdaq in September 2025 through a merger with Ares Acquisition Corporation II, valued at about $2.5 billion. It raised more than $212.5 million from institutional investors.", "kicker": "Apply the rule: technology can arrive before the rules.", "fullText": "Kodiak trucks run fully driverless on private roads in the Permian Basin oil field. Atlas Energy Solutions took delivery of eight driverless trucks as part of an initial 100-truck order.\n\nPrivate roads let Kodiak run without a driver while public highway rules are still being worked out.", "sources": [{"url": "https://www.ttnews.com/articles/autonomous-kodiak-goes-public", "label": "Transport Topics, autonomous truck developer Kodiak goes public"}, {"url": "https://techcrunch.com/2025/05/01/aurora-launches-commercial-self-driving-truck-service-in-texas", "label": "TechCrunch, Aurora launches self-driving truck service in Texas"}]}, "evidence": {"kind": "faceOff", "prompt": "Where are Kodiak's trucks running fully driverless?", "left": {"name": "Private Permian roads", "note": "Oil field routes"}, "right": {"name": "Every US interstate", "note": "Coast to coast"}, "correctIndex": 0, "explanation": "Kodiak runs fully driverless trucks on private roads in the Permian Basin."}, "numbers": {"kind": "numberSense", "prompt": "How many trucks were in Atlas Energy's initial order from Kodiak?", "min": 0, "max": 250, "value": 100, "unit": "trucks", "explanation": "An initial 100-truck order, with eight delivered."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at Kodiak. They ask why they started on private roads.", "prompt": "What is a strong answer?", "options": ["Oil fields pay drivers the most", "Fewer rules and simpler routes", "Public roads ban all heavy trucks"], "correctIndex": 1, "consequences": ["There is no driver to pay.", "You see why private roads are a first step.", "Trucks use public roads every day."], "explanation": "Private oil field roads let driverless trucks run while public rules develop."}, "proReasoning": "Strong candidates explain how a company picks its first market.", "commonMistake": "Assuming the technology alone decides where it runs.", "mentalModel": "Start where the rules allow."}, "invest": {"call": {"kind": "theCall", "situation": "Kodiak went public valued at about $2.5 billion with 8 trucks delivered.", "prompt": "What should an investor focus on?", "options": ["How bright the trucks are painted", "Whether oil prices fall next week", "How fast the 100-truck order is filled"], "correctIndex": 2, "consequences": ["Paint does not drive value.", "Weekly oil moves are noise.", "You track real deployment against promises."], "explanation": "The order shows demand. Delivering it shows the business works."}, "proReasoning": "Investors in early tech track deployment, not headlines.", "commonMistake": "Valuing a company on its listing alone.", "mentalModel": "Track deployment, not headlines."}, "build_startup": {"call": {"kind": "theCall", "situation": "Driverless trucks now run on private oil field roads.", "prompt": "What could a startup build alongside them?", "options": ["Remote support and maintenance tools", "A rival oil field for trucks", "Seats for drivers in driverless trucks"], "correctIndex": 0, "consequences": ["Driverless fleets still need support and upkeep.", "Oil fields are not a startup product.", "There is no driver to seat."], "explanation": "Fleets without drivers still need monitoring, support and maintenance."}, "proReasoning": "Founders build the support layer around new technology.", "commonMistake": "Competing with the core technology instead of supporting it.", "mentalModel": "Build the support layer."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why driverless trucks run in oil fields first.", "prompt": "Why there?", "options": ["Trucks are not used anywhere else", "Private roads avoid highway rules", "Oil fields have the fastest roads"], "correctIndex": 1, "consequences": ["Trucks are everywhere.", "You see rules shaping where technology runs.", "Speed is not the reason."], "explanation": "Private roads let companies run driverless trucks while public rules are unsettled."}, "proReasoning": "New technology often starts where rules are simplest.", "commonMistake": "Thinking technology goes wherever it works.", "mentalModel": "Rules decide where tech starts."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:cea1c0ac3234$ml$]::text[]),
($ml$ecfada60-97cc-5cef-b9cc-8dfdbb3c056e$ml$::uuid, $ml$logistics$ml$, 12, 2, $ml${"id": "logistics-d12-c2", "title": "A truck with no hours clock", "lessonTitle": "Trucks with no one inside", "slot": 2, "type": "connect", "brief": {"headline": "Aurora began driverless freight runs between Dallas and Houston in May 2025. A human truck driver is limited to 11 hours of driving in a 14-hour window.", "kicker": "Connect day 5 and day 12: hours limits meet driverless trucks.", "fullText": "Day 5 showed that hours rules cap how far a driver can take a load each day. Day 12 shows why driverless trucks matter: with no driver on board, there is no driver whose hours run out.\n\nAurora's early customers included Uber Freight and Hirschbach. Aurora owns, maintains and insures the trucks. It also sued over a federal rule on placing warning triangles, which assumes a person is in the cab.", "sources": [{"url": "https://techcrunch.com/2025/05/01/aurora-launches-commercial-self-driving-truck-service-in-texas", "label": "TechCrunch, Aurora launches self-driving truck service in Texas"}, {"url": "https://www.fmcsa.dot.gov/regulations/hours-service/summary-hours-service-regulations", "label": "FMCSA, hours of service summary"}]}, "evidence": {"kind": "sortSignal", "prompt": "True of Aurora's Texas launch or not?", "buckets": ["True", "Not true"], "items": [{"text": "Runs between Dallas and Houston", "bucket": 0}, {"text": "Aurora owns and insures the trucks", "bucket": 0}, {"text": "Uber Freight is a customer", "bucket": 0}, {"text": "Every rule now fits driverless trucks", "bucket": 1}], "explanation": "Aurora sued over the warning triangle rule, which shows rules have not caught up."}, "numbers": {"kind": "numberSense", "prompt": "How many hours can a human driver drive after 10 hours off?", "min": 0, "max": 20, "value": 11, "unit": "hours", "explanation": "Up to 11 hours of driving, within a 14-hour window."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work in operations at a carrier testing Aurora capacity.", "prompt": "What do you plan for?", "options": ["Firing every driver right away", "Using driverless trucks on all routes", "Handoffs to human drivers at each end"], "correctIndex": 2, "consequences": ["Driverless runs cover only some lanes.", "Service is limited to certain routes.", "You plan how driverless lanes join the network."], "explanation": "Driverless trucks run set lanes. Human drivers still handle the rest."}, "proReasoning": "Operators plan how new technology fits existing work.", "commonMistake": "Assuming new technology replaces everything at once.", "mentalModel": "Plan the handoffs."}, "invest": {"call": {"kind": "theCall", "situation": "Driverless trucks have no driver whose hours run out.", "prompt": "Why does that matter for investors?", "options": ["Each truck could run more hours a day", "Trucks will need no maintenance", "Fuel will become free"], "correctIndex": 0, "consequences": ["You see the utilization gain.", "Trucks still need upkeep.", "Fuel still costs money."], "explanation": "Without a driver's hours limit, a truck can run more of the day, if rules allow."}, "proReasoning": "Investors look for where new technology lifts asset use.", "commonMistake": "Overstating savings that are not there.", "mentalModel": "Find the real gain."}, "build_startup": {"call": {"kind": "theCall", "situation": "Aurora sued over a rule that assumes a person is in the cab.", "prompt": "Where is a startup opportunity?", "options": ["Hiring drivers to sit in empty trucks", "Tools that meet safety rules with no driver", "Lawsuits against every regulator"], "correctIndex": 1, "consequences": ["That removes the benefit.", "You solve the gap between rules and tech.", "Lawsuits are not a product."], "explanation": "Rules built for human drivers need new ways to meet them. Products can help."}, "proReasoning": "Founders find rules that new technology cannot yet meet.", "commonMistake": "Ignoring rules that assume a human is present.", "mentalModel": "Solve the rule gap."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why hours rules do not stop a driverless truck.", "prompt": "Why not?", "options": ["Driverless trucks are exempt from all rules", "They only drive at night", "The rules limit drivers, and there is none"], "correctIndex": 2, "consequences": ["Other rules still apply.", "They run in the day too.", "You see the rules apply to people."], "explanation": "Hours rules limit drivers. A truck without one is not limited the same way."}, "proReasoning": "Read rules for who they apply to.", "commonMistake": "Thinking driverless means rule-free.", "mentalModel": "Rules follow the driver."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:977fcb4c1db5$ml$]::text[]),
($ml$7d3d98db-2ba4-5f03-8150-f2ee384094b6$ml$::uuid, $ml$logistics$ml$, 12, 3, $ml${"id": "logistics-d12-c3", "title": "Try driverless on one lane?", "lessonTitle": "Trucks with no one inside", "slot": 3, "type": "decide", "brief": {"headline": "You run a Texas carrier with heavy freight between Dallas and Houston. A driverless truck company offers capacity on that lane.", "kicker": "Decide: pilot driverless capacity or wait?", "fullText": "Aurora began driverless runs between Dallas and Houston in May 2025, with customers including Uber Freight and Hirschbach. Aurora owns, maintains and insures its trucks. It also sued over a warning triangle rule that assumes a person is in the cab.\n\nYour drivers worry about their jobs. Your customers want reliable, on-time service.", "sources": [{"url": "https://techcrunch.com/2025/05/01/aurora-launches-commercial-self-driving-truck-service-in-texas", "label": "TechCrunch, Aurora launches self-driving truck service in Texas"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What is the most careful first step?", "options": ["A small pilot on part of the lane", "Switch the whole lane at once", "Refuse to ever try it"], "correctIndex": 0, "explanation": "A pilot tests reliability and cost without betting your whole lane."}, "numbers": {"kind": "numberSense", "prompt": "How many hours long is a driver's daily duty window?", "min": 0, "max": 24, "value": 14, "unit": "hours", "explanation": "Drivers cannot drive after the 14th hour on duty."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your drivers ask whether driverless trucks will take their jobs.", "prompt": "What do you say?", "options": ["It is a pilot on one lane; we will update you", "All jobs are safe forever, no matter what", "Everyone will be replaced next month"], "correctIndex": 0, "consequences": ["You are honest about the scope.", "No one can promise that.", "That is untrue and alarming."], "explanation": "Honest scope and updates keep trust while you test."}, "proReasoning": "Good managers explain change clearly and keep people informed.", "commonMistake": "Making promises you cannot keep.", "mentalModel": "Be honest about scope."}, "invest": {"call": {"kind": "theCall", "situation": "The carrier pilots driverless capacity on one lane.", "prompt": "What should an investor watch?", "options": ["The color of the driverless trucks", "Cost and on-time results versus drivers", "How many news stories mention it"], "correctIndex": 1, "consequences": ["Color is irrelevant.", "You track the results that decide scale.", "Press does not prove value."], "explanation": "The pilot's cost and reliability decide whether it scales."}, "proReasoning": "Investors judge pilots by results, not attention.", "commonMistake": "Rewarding a pilot for press coverage.", "mentalModel": "Judge pilots by results."}, "build_startup": {"call": {"kind": "theCall", "situation": "Carriers want to test driverless capacity on a few lanes.", "prompt": "What could you offer them?", "options": ["A driverless truck built in your garage", "A plan to replace all carriers", "Tools to compare driverless and driver runs"], "correctIndex": 2, "consequences": ["Building trucks takes huge capital.", "Carriers are your customers.", "You help them judge the pilot."], "explanation": "Carriers need clear comparisons to decide on scale."}, "proReasoning": "Founders help customers evaluate new technology.", "commonMistake": "Competing with the technology instead of helping buyers judge it.", "mentalModel": "Help buyers judge pilots."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why Aurora owns and insures its own trucks.", "prompt": "Why would it?", "options": ["It keeps control of safety and liability", "Carriers are not allowed to own trucks", "Insurance is free for driverless trucks"], "correctIndex": 0, "consequences": ["You see why the tech company holds the risk.", "Carriers own trucks every day.", "Insurance costs money."], "explanation": "Owning and insuring the trucks keeps safety and liability with Aurora."}, "proReasoning": "Whoever controls the risk often owns the asset.", "commonMistake": "Thinking ownership is only about money.", "mentalModel": "Control the risk, own the asset."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8b46207fb453$ml$]::text[]),
($ml$6923382b-74d8-515a-a457-c3689d4b083f$ml$::uuid, $ml$logistics$ml$, 13, 1, $ml${"id": "logistics-d13-c1", "title": "Fraud in a fragmented market", "lessonTitle": "Why brokers exist", "slot": 1, "type": "apply", "brief": {"headline": "Carrier vetting firm Highway said it blocked more than 400,000 freight fraud attempts in the first quarter of 2025. They included 352,134 fraudulent emails and 30,921 spoofed phone numbers.", "kicker": "Apply the rule: fragmentation creates middlemen and risk.", "fullText": "Highway also recorded 561 attempts to access accounts from 42 countries. The Transportation Intermediaries Association, citing the National Insurance Crime Bureau, pointed to a 1,500% increase in reported cargo theft since 2021.\n\nWith most carriers running only a handful of trucks, brokers must check thousands of small firms they have never met. Fraudsters pose as real carriers or brokers to steal loads or payments.", "sources": [{"url": "https://www.ajot.com/news/highway-releases-freight-fraud-index-revealing-400000-sophisticated-fraud-attempts-in-q1-2025", "label": "AJOT, Highway freight fraud index for Q1 2025"}, {"url": "https://fleetowner.com/research/truck-by-numbers/media-gallery/55338098/trucking-by-the-numbers-2025-overview-carrier-composition-costs-and-impact", "label": "FleetOwner, trucking by the numbers 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the chain in order.", "steps": ["Most carriers run only a few trucks", "Brokers book loads with firms they do not know", "Fraudsters pose as real carriers", "Brokers invest in vetting tools"], "explanation": "A fragmented market forces brokers to trust strangers, which fraudsters exploit."}, "numbers": {"kind": "numberSense", "prompt": "How many thousand fraudulent emails did Highway block in Q1 2025?", "min": 0, "max": 600, "value": 352, "unit": "K", "explanation": "352,134 fraudulent emails, part of more than 400,000 attempts."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You start in carrier sales at a broker. A new carrier emails asking for a load.", "prompt": "What do you do first?", "options": ["Book it fast before a rival does", "Trust the email since it looks official", "Verify the carrier through trusted checks"], "correctIndex": 2, "consequences": ["Speed without checks invites fraud.", "Spoofed emails often look official.", "You check before handing over freight."], "explanation": "Fraudsters pose as real carriers. Checks protect the load and the shipper."}, "proReasoning": "Good carrier reps verify every new partner before booking.", "commonMistake": "Trusting an email address or a logo.", "mentalModel": "Verify before you book."}, "invest": {"call": {"kind": "theCall", "situation": "Freight fraud is rising across a fragmented carrier market.", "prompt": "What could benefit from that trend?", "options": ["Firms that vet and verify carriers", "Brokers that skip any carrier checks", "Carriers that refuse to use email"], "correctIndex": 0, "consequences": ["Demand for trust tools rises with fraud.", "Skipping checks raises losses.", "Avoiding email does not stop fraud."], "explanation": "Rising fraud raises demand for vetting and identity checks."}, "proReasoning": "Investors look for who sells the fix to a growing risk.", "commonMistake": "Seeing only the cost of fraud, not the market it creates.", "mentalModel": "Risk creates a market for trust."}, "build_startup": {"call": {"kind": "theCall", "situation": "Fraudsters used 30,921 spoofed phone numbers in one quarter.", "prompt": "What product could help brokers?", "options": ["A rule to book only by phone", "Checks that confirm who is really calling", "A bigger call center to answer faster"], "correctIndex": 1, "consequences": ["Phones were spoofed too.", "You attack the identity problem directly.", "More calls do not stop spoofing."], "explanation": "Spoofed calls and emails exploit trust. Identity checks close that gap."}, "proReasoning": "Founders target the specific trick fraudsters use.", "commonMistake": "Solving the volume of calls instead of their honesty.", "mentalModel": "Confirm who you are dealing with."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why freight is a target for fraud.", "prompt": "What makes it vulnerable?", "options": ["Every load is guarded by police", "Trucks rarely leave the depot at all", "Many small firms who are strangers"], "correctIndex": 2, "consequences": ["Most loads are not guarded.", "Trucks move constantly.", "You see how fragmentation creates openings."], "explanation": "Brokers deal with thousands of small carriers. Fraudsters hide among them."}, "proReasoning": "Fragmented markets need trust, and trust can be faked.", "commonMistake": "Thinking fraud only happens online.", "mentalModel": "Strangers trading invites fraud."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:24681a730702$ml$]::text[]),
($ml$baade4e5-7b4a-5c01-98a2-1c48d9abd6d1$ml$::uuid, $ml$logistics$ml$, 13, 2, $ml${"id": "logistics-d13-c2", "title": "Why brokers can own nothing", "lessonTitle": "Why brokers exist", "slot": 2, "type": "connect", "brief": {"headline": "91.5% of US carriers run fewer than 10 trucks, and 52.9% run just one. A large broker works with over 450,000 providers.", "kicker": "Connect day 2 and day 13: asset-light works because carriers are small.", "fullText": "Day 2 showed that brokers own very little equipment and sell access to trucks instead. Day 13 shows why that model exists: carrier supply is split among about 1.1 million for-hire carriers, plus about 791,000 private fleets.\n\nA shipper cannot call thousands of one-truck firms. A broker gathers them into one network, which is how C.H. Robinson can serve about 75,000 customers with 450,000 providers.", "sources": [{"url": "https://fleetowner.com/research/truck-by-numbers/media-gallery/55338098/trucking-by-the-numbers-2025-overview-carrier-composition-costs-and-impact", "label": "FleetOwner, trucking by the numbers 2025"}, {"url": "https://www.sec.gov/Archives/edgar/data/1043277/000104327726000009/chrw-20251231.htm", "label": "C. H. Robinson 10-K, 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Which market needs brokers more?", "left": {"name": "Many tiny carriers", "note": "Most run one truck"}, "right": {"name": "Three giant carriers", "note": "Each covers the country"}, "correctIndex": 0, "explanation": "Brokers add value by connecting shippers to many small carriers."}, "numbers": {"kind": "numberSense", "prompt": "What share of US carriers run just one truck?", "min": 0, "max": 80, "value": 52.9, "unit": "%", "explanation": "52.9% run one truck, and 91.5% run fewer than 10."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a broker. They ask why their business exists.", "prompt": "What is your answer?", "options": ["Carriers are tiny; shippers need one contact", "Shippers dislike dealing with trucks and drivers", "Brokers own the largest truck fleets"], "correctIndex": 0, "consequences": ["You explain the fragmentation that creates brokers.", "Shippers need trucks.", "Brokers own little equipment."], "explanation": "With most carriers so small, shippers need someone to gather capacity."}, "proReasoning": "Candidates who explain the market structure show real understanding.", "commonMistake": "Describing brokers as unnecessary middlemen.", "mentalModel": "Fragmentation creates the broker."}, "invest": {"call": {"kind": "theCall", "situation": "Most carriers are tiny, and brokers connect them to shippers.", "prompt": "What would hurt the broker model?", "options": ["Shippers posting more loads", "Carriers merging into a few big firms", "More one-truck carriers entering"], "correctIndex": 1, "consequences": ["More loads help brokers.", "Consolidated carriers need brokers less.", "More small carriers help brokers."], "explanation": "Brokers thrive on fragmentation. Consolidation would weaken their role."}, "proReasoning": "Investors watch the market structure that a business model depends on.", "commonMistake": "Ignoring what a model needs to stay true.", "mentalModel": "Know what your model depends on."}, "build_startup": {"call": {"kind": "theCall", "situation": "More than half of carriers run just one truck.", "prompt": "What do those owner-operators need?", "options": ["Software built for 5,000-truck fleets", "Expensive tools sold only yearly", "Easy ways to find loads and get paid"], "correctIndex": 2, "consequences": ["Large fleet tools miss them.", "Small firms need simple, cheap tools.", "You serve the real size of most carriers."], "explanation": "One-truck firms need simple load finding and fast payment."}, "proReasoning": "Founders design for the typical customer, not the biggest.", "commonMistake": "Building for giants in a market of tiny firms.", "mentalModel": "Build for the typical carrier."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder how a broker can work with 450,000 providers.", "prompt": "How is that possible?", "options": ["Most are small and book loads online", "Each provider is a huge national fleet", "The broker owns all of them outright"], "correctIndex": 0, "consequences": ["You see technology matching many small firms.", "Most carriers are small.", "Brokers own little equipment."], "explanation": "Most carriers are tiny. Brokers use networks and software to reach them."}, "proReasoning": "Big networks of small suppliers need a coordinator.", "commonMistake": "Assuming providers must be large companies.", "mentalModel": "Coordinate the many."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:37446d5eb418$ml$]::text[]),
($ml$7383d4e9-0bd0-546e-8d1d-9cdaee80e5fd$ml$::uuid, $ml$logistics$ml$, 13, 3, $ml${"id": "logistics-d13-c3", "title": "Broker or build your own list?", "lessonTitle": "Why brokers exist", "slot": 3, "type": "decide", "brief": {"headline": "You manage freight for a manufacturer shipping 50 truckloads a week across many lanes. You use brokers today and pay their margin.", "kicker": "Decide: keep brokers or book carriers yourself?", "fullText": "About 91.5% of US carriers run fewer than 10 trucks. Brokers gather that scattered capacity, check carriers and handle problems, and earn a margin for it.\n\nBooking carriers directly could save that margin. It would also mean vetting many small carriers yourself, at a time when freight fraud is rising.", "sources": [{"url": "https://fleetowner.com/research/truck-by-numbers/media-gallery/55338098/trucking-by-the-numbers-2025-overview-carrier-composition-costs-and-impact", "label": "FleetOwner, trucking by the numbers 2025"}, {"url": "https://www.ajot.com/news/highway-releases-freight-fraud-index-revealing-400000-sophisticated-fraud-attempts-in-q1-2025", "label": "AJOT, Highway freight fraud index for Q1 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Favors brokers or booking direct?", "buckets": ["Brokers", "Direct"], "items": [{"text": "Many lanes, each with few loads", "bucket": 0}, {"text": "Little staff to vet carriers", "bucket": 0}, {"text": "Steady loads on a few lanes", "bucket": 1}, {"text": "A trusted carrier on a busy lane", "bucket": 1}], "explanation": "Scattered, thin lanes favor brokers. Dense, steady lanes can go direct."}, "numbers": {"kind": "numberSense", "prompt": "What share of US carriers run fewer than 10 trucks?", "min": 0, "max": 100, "value": 91.5, "unit": "%", "explanation": "91.5% of carriers run fewer than 10 trucks."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss wants to cut broker costs.", "prompt": "What do you propose?", "options": ["Keep brokers everywhere, with no changes", "Go direct on busy lanes; broker the rest", "Drop all brokers by next week"], "correctIndex": 1, "consequences": ["You miss real savings on busy lanes.", "You save where direct works and keep coverage elsewhere.", "Going direct overnight risks service and fraud."], "explanation": "Dense lanes justify direct contracts. Thin lanes still need brokers."}, "proReasoning": "Good freight managers mix models by lane.", "commonMistake": "Making one choice for every lane.", "mentalModel": "Mix models by lane."}, "invest": {"call": {"kind": "theCall", "situation": "Large shippers are moving dense lanes away from brokers.", "prompt": "What does that mean for brokers?", "options": ["They gain more easy steady freight", "They must buy trucks to survive", "More focus on thin, hard-to-fill lanes"], "correctIndex": 2, "consequences": ["Steady lanes are the ones leaving.", "Buying trucks is not required.", "Brokers keep the lanes direct deals cannot fill."], "explanation": "Shippers take easy lanes direct. Brokers earn on the harder ones."}, "proReasoning": "Investors look at which freight stays with brokers.", "commonMistake": "Assuming all freight is equally easy to take direct.", "mentalModel": "Brokers earn on the hard loads."}, "build_startup": {"call": {"kind": "theCall", "situation": "Shippers want to go direct on some lanes but fear fraud.", "prompt": "What could help them?", "options": ["Carrier vetting tools for shippers", "A new broker that owns trucks", "A promise that fraud has ended"], "correctIndex": 0, "consequences": ["You give shippers the checks brokers provide.", "That is a different model.", "Fraud is rising."], "explanation": "Going direct means doing the vetting brokers did. Tools can help."}, "proReasoning": "Founders unbundle what a middleman does for buyers who want it.", "commonMistake": "Ignoring the risk that kept shippers with brokers.", "mentalModel": "Unbundle the middleman."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why the manufacturer pays brokers at all.", "prompt": "What do brokers provide?", "options": ["Lower fuel prices on every lane", "Access to scattered carriers, plus checks", "Trucks they own and drive themselves"], "correctIndex": 1, "consequences": ["Fuel prices are set by markets.", "You see the service behind the margin.", "Brokers own little equipment."], "explanation": "Brokers gather small carriers and vet them, saving shippers that work."}, "proReasoning": "A margin pays for work someone else would have to do.", "commonMistake": "Seeing a middleman as pure cost.", "mentalModel": "Margins pay for work."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:213c993b9f0f$ml$]::text[]),
($ml$f3944278-f9b6-50f8-8e2b-c739119c6f40$ml$::uuid, $ml$logistics$ml$, 14, 1, $ml${"id": "logistics-d14-c1", "title": "A broker squeezed on margin", "lessonTitle": "Fewer people, better margins", "slot": 1, "type": "apply", "brief": {"headline": "RXO posted fourth-quarter 2025 revenue of $1.47 billion, down 11.9%, and a net loss of $46 million. Its truck brokerage gross margin was 11.9%.", "kicker": "Apply the rule: margin comes from loads per person.", "fullText": "Truck brokerage revenue fell 13.7% to $1.09 billion, and brokerage volumes fell 4%, though less-than-truckload volumes rose 31%. Full-year revenue was $5.74 billion, up from $4.55 billion after the Coyote deal, with a net loss of $100 million.\n\nCEO Drew Wilkerson said carrier costs \"impacted our buy rates and squeezed our brokerage gross margin.\" When carriers charge more and shippers do not pay more, the broker's spread shrinks.", "sources": [{"url": "https://www.ttnews.com/articles/rxo-earnings-q4-2025", "label": "Transport Topics, RXO fourth-quarter 2025 results"}, {"url": "https://www.freightwaves.com/news/headcount-falls-at-c-h-robinson-as-automation-ai-reshape-brokerage", "label": "FreightWaves, headcount falls at C.H. Robinson as automation reshapes brokerage"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What squeezed RXO's brokerage margin?", "options": ["Shippers paying far more per load", "Selling its truck fleet", "Higher costs to buy truck capacity"], "correctIndex": 2, "explanation": "Rising carrier costs raised RXO's buy rates faster than its sell rates."}, "numbers": {"kind": "numberSense", "prompt": "What was RXO's full-year 2025 revenue, in billion dollars?", "min": 0, "max": 10, "value": 5.7, "unit": "B", "explanation": "$5.74 billion, up from $4.55 billion after buying Coyote."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You price loads at a broker. Carrier costs jump but shippers resist price rises.", "prompt": "What do you watch most closely?", "options": ["The spread on each load you book", "The number of loads only", "The colors on your dashboards"], "correctIndex": 0, "consequences": ["You protect margin, not just volume.", "Volume at a loss hurts results.", "Dashboards do not change margins."], "explanation": "When buy rates rise faster than sell rates, the spread shrinks."}, "proReasoning": "Good pricers watch the spread load by load.", "commonMistake": "Chasing volume while margins vanish.", "mentalModel": "Watch the spread."}, "invest": {"call": {"kind": "theCall", "situation": "RXO revenue rose for the year after buying Coyote, but it lost $100 million.", "prompt": "What does an investor take from that?", "options": ["Revenue is all that matters", "Bigger revenue did not bring profit", "The deal clearly created profit"], "correctIndex": 1, "consequences": ["Profit matters more than size.", "You separate size from earnings.", "The year ended in a loss."], "explanation": "Revenue grew through the deal, but margins and costs left a net loss."}, "proReasoning": "Investors look past revenue growth to margins.", "commonMistake": "Celebrating growth that came from buying another firm.", "mentalModel": "Size is not profit."}, "build_startup": {"call": {"kind": "theCall", "situation": "Brokers face thin margins as carrier costs rise.", "prompt": "What could help them?", "options": ["More sales staff to book more loads", "Ads to raise brand awareness online", "Pricing tools tracking buy and sell rates"], "correctIndex": 2, "consequences": ["More staff adds cost.", "Ads do not fix margins.", "You help them protect the spread."], "explanation": "Brokers need fast, accurate pricing to protect thin margins."}, "proReasoning": "Founders build for the metric under the most pressure.", "commonMistake": "Adding headcount when margins are thin.", "mentalModel": "Protect the spread."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder how rising truck costs hurt a company that owns no trucks.", "prompt": "How does it happen?", "options": ["It pays carriers more, charges the same", "It is forced to buy its own trucks", "Its office rents went up sharply"], "correctIndex": 0, "consequences": ["You see the spread getting squeezed.", "Brokers do not need to buy trucks.", "Offices are a small cost."], "explanation": "A broker buys capacity and resells it. If buying costs more, the spread shrinks."}, "proReasoning": "Middlemen feel price changes on both sides.", "commonMistake": "Thinking asset-light means risk-free.", "mentalModel": "Squeezed in the middle."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:cebcb85cfede$ml$]::text[]),
($ml$ae4627e1-4444-51ef-ac89-076050deb08b$ml$::uuid, $ml$logistics$ml$, 14, 2, $ml${"id": "logistics-d14-c2", "title": "Automation without the crash", "lessonTitle": "Fewer people, better margins", "slot": 2, "type": "connect", "brief": {"headline": "C.H. Robinson cut headcount by about 19%, from about 14,990 to 12,085, from early 2024 to late 2025. Its North American truckload unit's adjusted operating margin rose to 36.4%.", "kicker": "Connect day 6 and day 14: automation pays when it cuts costs.", "fullText": "Day 6 showed Convoy, whose software automated the carrier side for 98% of loads, could not survive the downturn. Day 14 shows a large broker using automation to lift margins: from 33.3% to 36.4% in its North American Surface Transportation unit.\n\nIt did that while shipments fell for 13 straight quarters. Automation helped when it lowered the cost of each load, not when it simply grew volume.", "sources": [{"url": "https://www.freightwaves.com/news/headcount-falls-at-c-h-robinson-as-automation-ai-reshape-brokerage", "label": "FreightWaves, headcount falls at C.H. Robinson as automation reshapes brokerage"}, {"url": "https://techcrunch.com/2023/11/01/flexport-acquires-technology-of-former-digital-freight-unicorn-convoy", "label": "TechCrunch, Flexport acquires technology of former digital freight unicorn Convoy"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Headcount fell about 19% over the period.", "The unit's margin rose to 36.4%.", "Shipments rose for 13 straight quarters."], "fakeIndex": 2, "explanation": "Shipments fell for 13 straight quarters while margins rose."}, "numbers": {"kind": "numberSense", "prompt": "About how many thousand employees did C.H. Robinson have in late 2025?", "min": 0, "max": 20, "value": 12.1, "unit": "K", "explanation": "About 12,085, down from about 14,990."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work at a broker adopting AI tools.", "prompt": "What skill becomes more valuable?", "options": ["Answering every routine email", "Handling exceptions tools cannot", "Typing quotes by hand faster"], "correctIndex": 1, "consequences": ["Routine emails are being automated.", "You focus on what automation leaves to people.", "Routine quoting is what gets automated."], "explanation": "Automation takes routine tasks. People handle the hard cases."}, "proReasoning": "Staff who thrive with automation move to judgment and exceptions.", "commonMistake": "Competing with software on routine work.", "mentalModel": "Do what tools cannot."}, "invest": {"call": {"kind": "theCall", "situation": "A broker's margin rose while its shipments fell.", "prompt": "What explains it?", "options": ["Shipments rising every quarter", "Buying more trucks", "Lower cost per load from automation"], "correctIndex": 2, "consequences": ["Shipments fell.", "Brokers own little equipment.", "You see productivity driving margin."], "explanation": "Fewer people handled the work, so each load cost less."}, "proReasoning": "Investors look at productivity, not just volume.", "commonMistake": "Assuming margins only rise with volume.", "mentalModel": "Productivity drives margin."}, "build_startup": {"call": {"kind": "theCall", "situation": "Convoy automated loads and failed; C.H. Robinson automated and lifted margins.", "prompt": "What is the lesson for a founder?", "options": ["Automation must cut cost, not add speed", "Automation always guarantees success", "Never automate anything at all"], "correctIndex": 0, "consequences": ["You tie tech to unit economics.", "Convoy shows it does not.", "Automation helped the large broker."], "explanation": "Automation works when it lowers cost per load in a market you can survive."}, "proReasoning": "Founders measure tech by the cost it removes.", "commonMistake": "Treating automation as the business itself.", "mentalModel": "Measure tech by cost removed."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder how fewer people can mean better margins.", "prompt": "How does it work?", "options": ["Prices rose sharply", "Each person handles more loads", "Each person works fewer hours"], "correctIndex": 1, "consequences": ["The source credits productivity.", "You see loads per person rising.", "Hours are not the driver."], "explanation": "Automation lets each person handle more work, so costs fall per load."}, "proReasoning": "Margin is often a story about productivity.", "commonMistake": "Thinking margins only come from higher prices.", "mentalModel": "More loads per person."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8fe44f40db65$ml$]::text[]),
($ml$1397d7c1-a67e-5664-ab2f-4d96cbffa81e$ml$::uuid, $ml$logistics$ml$, 14, 3, $ml${"id": "logistics-d14-c3", "title": "New tools, fewer roles?", "lessonTitle": "Fewer people, better margins", "slot": 3, "type": "decide", "brief": {"headline": "You run a mid-size freight broker. New AI tools can handle routine quotes and carrier check-calls, and freight volumes are flat.", "kicker": "Decide: cut roles, redeploy people or grow loads?", "fullText": "C.H. Robinson cut headcount by about 19% from early 2024 to late 2025 and lifted its truckload unit margin to 36.4%, even as shipments fell. RXO, by contrast, saw its brokerage margin squeezed by higher carrier costs.\n\nYour team spends much of its day on routine work the tools can do.", "sources": [{"url": "https://www.freightwaves.com/news/headcount-falls-at-c-h-robinson-as-automation-ai-reshape-brokerage", "label": "FreightWaves, headcount falls at C.H. Robinson as automation reshapes brokerage"}, {"url": "https://www.ttnews.com/articles/rxo-earnings-q4-2025", "label": "Transport Topics, RXO fourth-quarter 2025 results"}]}, "evidence": {"kind": "faceOff", "prompt": "Which raises loads per person?", "left": {"name": "Automate routine tasks", "note": "People handle exceptions"}, "right": {"name": "Hire more staff", "note": "Same tasks, more people"}, "correctIndex": 0, "explanation": "Automation lets each person handle more loads. Hiring adds cost for the same work."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did C.H. Robinson's headcount fall from early 2024 to late 2025?", "min": 0, "max": 50, "value": 19, "unit": "%", "explanation": "About 19%, from about 14,990 to 12,085."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You lead a team of brokers. The tools will take half their routine work.", "prompt": "What do you do with the time freed?", "options": ["Let everyone keep the old routine", "Ban the tools to protect jobs", "Move people to finding new customers"], "correctIndex": 2, "consequences": ["You waste the gain.", "You fall behind rivals.", "You turn saved time into growth."], "explanation": "Freed time can go to sales and service that grow the business."}, "proReasoning": "Good managers redeploy time saved by automation.", "commonMistake": "Adopting tools but changing nothing else.", "mentalModel": "Redeploy the saved time."}, "invest": {"call": {"kind": "theCall", "situation": "A broker adopts AI tools with flat freight volumes.", "prompt": "What metric shows whether it is working?", "options": ["Loads handled per employee", "Total number of tools bought", "Size of the office"], "correctIndex": 0, "consequences": ["You measure the productivity gain.", "Tools bought is not results.", "Office size says nothing."], "explanation": "If tools work, loads per employee rise and margins follow."}, "proReasoning": "Investors track productivity metrics during automation.", "commonMistake": "Counting tools instead of results.", "mentalModel": "Measure loads per person."}, "build_startup": {"call": {"kind": "theCall", "situation": "Brokers want automation but worry about service quality.", "prompt": "What would you build?", "options": ["A system with no human review at all", "Tools that flag exceptions for a human", "Bots that hide every issue from staff"], "correctIndex": 1, "consequences": ["No review risks costly mistakes.", "You keep people on the hard cases.", "Hidden problems hurt service."], "explanation": "Automation works best when it handles routine work and sends exceptions to people."}, "proReasoning": "Founders design automation with humans for edge cases.", "commonMistake": "Removing people from every decision.", "mentalModel": "Route exceptions to people."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why a broker would automate when volumes are flat.", "prompt": "Why would it?", "options": ["To make volumes grow overnight", "Because rules require it", "To raise margin without more loads"], "correctIndex": 2, "consequences": ["Tools do not create demand.", "No rule requires it.", "You see cost, not volume, as the lever."], "explanation": "With flat volume, lowering cost per load is the main way to lift margin."}, "proReasoning": "When revenue is flat, look at cost.", "commonMistake": "Thinking growth is the only path to profit.", "mentalModel": "Flat sales, cut costs."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6c49b4de63de$ml$]::text[]),
($ml$8feb979f-f974-5307-b481-83c9faef959c$ml$::uuid, $ml$logistics$ml$, 15, 1, $ml${"id": "logistics-d15-c1", "title": "Trusts must be close to cash", "lessonTitle": "The bond that protects carriers", "slot": 1, "type": "apply", "brief": {"headline": "FMCSA's tighter rule turned the $75,000 broker bond into a rigidly enforced floor, FreightWaves reported. Assets in BMC-85 trusts must be cash equivalents that can be sold within seven days or less.", "kicker": "Apply the rule: carrier protection must be real money.", "fullText": "Brokers must keep $75,000 of financial security so carriers can be paid if a broker fails. Many meet it with a surety bond, while thousands use BMC-85 trust funds.\n\nUnder the rule, trust assets must be cash or close to it. A trust holding assets that cannot be turned into cash quickly no longer counts, so some brokers must restructure how they hold the money.", "sources": [{"url": "https://www.freightwaves.com/news/fmcsas-tighter-bond-enforcement-looms-over-freight-brokers-in-2026", "label": "FreightWaves, FMCSA's tighter bond enforcement looms over brokers"}, {"url": "https://www.overdriveonline.com/regulations/article/15814887/fmcsa-rule-cracking-down-on-brokers-takes-effect", "label": "Overdrive, FMCSA rule cracking down on brokers takes effect"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which trust asset fits the new rule best?", "options": ["Shares in a private company", "Cash in a bank account", "Real estate held for years"], "correctIndex": 1, "explanation": "Trust assets must be cash equivalents that can be sold within seven days or less."}, "numbers": {"kind": "numberSense", "prompt": "What is the minimum broker financial security, in thousand dollars?", "min": 0, "max": 200, "value": 75, "unit": "K", "explanation": "Brokers must keep $75,000 of financial security."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work in compliance at a broker with a BMC-85 trust.", "prompt": "What do you check first?", "options": ["Whether carriers know the trust exists", "Whether trust assets are cash equivalents", "Whether the trust has a nice name"], "correctIndex": 1, "consequences": ["Carrier awareness does not meet the rule.", "You test the trust against the rule.", "The name does not matter."], "explanation": "Trust assets must be cash or close to it. Anything else may not count."}, "proReasoning": "Compliance staff check the substance, not the label.", "commonMistake": "Assuming an existing trust still qualifies.", "mentalModel": "Check the assets, not the label."}, "invest": {"call": {"kind": "theCall", "situation": "Thousands of brokers use trusts that may need restructuring.", "prompt": "Who could gain from that?", "options": ["Brokers holding illiquid assets", "Shippers paying slower", "Surety bond providers"], "correctIndex": 2, "consequences": ["Those brokers face the most change.", "Shippers are not the focus.", "Some brokers may switch to bonds."], "explanation": "Brokers that cannot meet trust rules may buy surety bonds instead."}, "proReasoning": "Investors look for who sells the fix to a new rule.", "commonMistake": "Missing the second-order effect of a rule.", "mentalModel": "Rules shift demand."}, "build_startup": {"call": {"kind": "theCall", "situation": "Brokers must prove their security is real and liquid.", "prompt": "What could you build?", "options": ["Live status of bonds and trusts", "A tool to hide low balances", "A trust that holds only artwork"], "correctIndex": 0, "consequences": ["You help brokers and carriers check status.", "Hiding balances defeats the rule.", "Artwork is not a cash equivalent."], "explanation": "Carriers and brokers both benefit from clear, live status of financial security."}, "proReasoning": "Founders build transparency where rules demand it.", "commonMistake": "Building around the rule instead of with it.", "mentalModel": "Make compliance visible."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why it matters whether trust money is cash.", "prompt": "Why does it?", "options": ["Banks require it for every kind of trust", "Carriers must be paid fast if a broker fails", "Cash earns the highest returns of all"], "correctIndex": 1, "consequences": ["This is an FMCSA rule.", "You see the point of the protection.", "Returns are not the purpose."], "explanation": "Security exists to pay carriers. It only helps if it can be paid out fast."}, "proReasoning": "Protection only works if it can be used quickly.", "commonMistake": "Thinking any asset is as good as cash.", "mentalModel": "Protection must be liquid."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ac6edf7b443e$ml$]::text[]),
($ml$84635f0f-1a74-53e9-9926-2474628b6d68$ml$::uuid, $ml$logistics$ml$, 15, 2, $ml${"id": "logistics-d15-c2", "title": "Protecting the one-truck carrier", "lessonTitle": "The bond that protects carriers", "slot": 2, "type": "connect", "brief": {"headline": "From January 16, 2026, FMCSA can suspend a broker's authority if its financial security falls below $75,000. 52.9% of US carriers run just one truck.", "kicker": "Connect day 13 and day 15: small carriers need payment protection.", "fullText": "Day 13 showed that most carriers are tiny, which is why brokers exist. Day 15 shows the protection for those carriers: brokers must keep $75,000 of security, and a broker that falls below it gets seven calendar days after notice to restore it.\n\nA one-truck carrier that hauls a load and does not get paid can be hurt badly. The bond rule gives regulators a fast way to act.", "sources": [{"url": "https://www.overdriveonline.com/regulations/article/15814887/fmcsa-rule-cracking-down-on-brokers-takes-effect", "label": "Overdrive, FMCSA rule cracking down on brokers takes effect"}, {"url": "https://fleetowner.com/research/truck-by-numbers/media-gallery/55338098/trucking-by-the-numbers-2025-overview-carrier-composition-costs-and-impact", "label": "FleetOwner, trucking by the numbers 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the steps in order.", "steps": ["A broker's security drops below $75,000", "FMCSA sends a notice", "The broker has seven days to restore it", "If not restored, authority can be suspended"], "explanation": "The rule gives brokers a short window, then lets FMCSA suspend authority."}, "numbers": {"kind": "numberSense", "prompt": "How many calendar days does a broker have to restore its security after notice?", "min": 0, "max": 30, "value": 7, "unit": "days", "explanation": "Seven calendar days after notice."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You run dispatch for a one-truck carrier. A new broker offers a load.", "prompt": "What do you check?", "options": ["That the broker's website looks nice", "That the rate is the highest you have seen", "That its authority and security are active"], "correctIndex": 2, "consequences": ["Websites can be faked.", "A high rate means nothing if unpaid.", "You protect yourself from unpaid loads."], "explanation": "Active authority and security mean someone stands behind payment."}, "proReasoning": "Careful carriers check broker status before hauling.", "commonMistake": "Taking the best rate without checking who pays.", "mentalModel": "Check who stands behind payment."}, "invest": {"call": {"kind": "theCall", "situation": "FMCSA can now suspend brokers whose security drops below $75,000.", "prompt": "What does that mean for the broker market?", "options": ["Weakly funded brokers may exit", "Brokers will need fewer funds", "Carriers lose protection"], "correctIndex": 0, "consequences": ["You see the rule raising the floor.", "The rule tightens funding.", "Carriers gain protection."], "explanation": "Brokers that cannot keep their security face suspension."}, "proReasoning": "Investors watch rules that remove weaker competitors.", "commonMistake": "Ignoring how rules reshape a market.", "mentalModel": "Rules raise the floor."}, "build_startup": {"call": {"kind": "theCall", "situation": "Small carriers need to know which brokers are safe to haul for.", "prompt": "What could you offer?", "options": ["A load board with no checks on anyone", "Live checks on broker authority and bonds", "A broker rating based on logos alone"], "correctIndex": 1, "consequences": ["No checks means more risk.", "You give carriers the facts they need.", "Logos prove nothing."], "explanation": "Carriers benefit from live status checks on brokers."}, "proReasoning": "Founders give the weaker side of a market better information.", "commonMistake": "Building trust signals that can be faked.", "mentalModel": "Give carriers real facts."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why the bond rule matters so much to small carriers.", "prompt": "Why does it?", "options": ["Small carriers own many trucks", "Carriers pay for the broker bond", "One unpaid load can hurt a tiny firm"], "correctIndex": 2, "consequences": ["Most run one truck.", "Brokers hold the bond.", "You see their exposure."], "explanation": "A one-truck carrier depends on every payment. Security protects it."}, "proReasoning": "Protection matters most to those with the least cushion.", "commonMistake": "Thinking only big firms need protection.", "mentalModel": "Small firms need protection most."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d2586ad7041e$ml$]::text[]),
($ml$1f157fe3-654a-56a2-8b30-02e8728a67c0$ml$::uuid, $ml$logistics$ml$, 15, 3, $ml${"id": "logistics-d15-c3", "title": "Your trust no longer qualifies", "lessonTitle": "The bond that protects carriers", "slot": 3, "type": "decide", "brief": {"headline": "You run a small freight broker. Your $75,000 BMC-85 trust holds assets that cannot be sold within seven days.", "kicker": "Decide: how do you meet the rule in time?", "fullText": "Under FMCSA's tighter enforcement, trust assets must be cash equivalents that can be sold within seven days or less. Since January 16, 2026, FMCSA can suspend a broker's authority if its security falls below $75,000.\n\nYou can move the trust into cash, switch to a surety bond, or do nothing and hope the trust is not checked.", "sources": [{"url": "https://www.freightwaves.com/news/fmcsas-tighter-bond-enforcement-looms-over-freight-brokers-in-2026", "label": "FreightWaves, FMCSA's tighter bond enforcement looms over brokers"}, {"url": "https://www.overdriveonline.com/regulations/article/15814887/fmcsa-rule-cracking-down-on-brokers-takes-effect", "label": "Overdrive, FMCSA rule cracking down on brokers takes effect"}]}, "evidence": {"kind": "sortSignal", "prompt": "Meets the rule or not?", "buckets": ["Meets it", "Does not"], "items": [{"text": "Trust moved into cash", "bucket": 0}, {"text": "A $75,000 surety bond", "bucket": 0}, {"text": "Trust kept in slow-to-sell assets", "bucket": 1}, {"text": "Security below $75,000", "bucket": 1}], "explanation": "Cash in trust or a surety bond meets the rule. Illiquid or short security does not."}, "numbers": {"kind": "numberSense", "prompt": "Within how many days must trust assets be sellable?", "min": 0, "max": 30, "value": 7, "unit": "days", "explanation": "Seven days or less."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You are the broker's finance lead.", "prompt": "What do you recommend?", "options": ["Fix it now: cash trust or a surety bond", "Wait and hope no one ever checks", "Close the whole business down today"], "correctIndex": 0, "consequences": ["You protect the company's authority.", "Suspension could stop all bookings.", "Closing is far more than needed."], "explanation": "Fixing it early avoids suspension and keeps the business running."}, "proReasoning": "Finance leads fix compliance gaps before regulators find them.", "commonMistake": "Hoping a known gap goes unnoticed.", "mentalModel": "Fix known gaps early."}, "invest": {"call": {"kind": "theCall", "situation": "You are considering investing in this small broker.", "prompt": "What do you ask first?", "options": ["What color its logo is", "How it will meet the security rule", "How many trucks it plans to buy"], "correctIndex": 1, "consequences": ["Logos do not matter.", "You check the risk to its authority.", "Brokers need few trucks."], "explanation": "Without compliant security, the broker could lose its authority."}, "proReasoning": "Investors check licenses and compliance before growth plans.", "commonMistake": "Looking at growth before survival.", "mentalModel": "Check the license first."}, "build_startup": {"call": {"kind": "theCall", "situation": "Many small brokers face the same trust problem.", "prompt": "What could you offer them?", "options": ["Advice on hiding illiquid assets", "A loan of artwork as security", "A simple path to cash trusts or bonds"], "correctIndex": 2, "consequences": ["Hiding assets breaks the rule.", "Artwork is not cash.", "You solve a common compliance need."], "explanation": "Brokers need an easy, compliant way to hold their security."}, "proReasoning": "Founders turn a new compliance burden into a simple product.", "commonMistake": "Offering workarounds instead of solutions.", "mentalModel": "Make compliance easy."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why a surety bond also satisfies the rule.", "prompt": "Why does it?", "options": ["A surety company guarantees payment", "Bonds earn interest for carriers", "Bonds are exempt from all rules"], "correctIndex": 0, "consequences": ["You see how a guarantee replaces cash.", "Interest is not the point.", "Bonds must meet rules too."], "explanation": "A surety bond means a company promises to pay carriers if the broker fails."}, "proReasoning": "A strong guarantee can stand in for cash.", "commonMistake": "Thinking only cash can protect carriers.", "mentalModel": "A guarantee can replace cash."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c9009f7d7b2e$ml$]::text[])
